    {
      "path": "dsh-pet/src/host/index.ts",
      "content": "/**\n * 插件入口：Cordis 插件，把 host 半侧的配置、路由、斜杠命令、轮询与桌面 Helper 装配到 ctx。\n * 装配顺序不能改：`getHandlePetRoute` 惰性取用（`httpRoute` 在本函数后段才创建），`startHelper` 必须最后调用。\n * @module dsh-pet/src/host/index\n */\nimport { createHostSetup } from './plugin/setup.ts';\nimport { readAllConfig } from './config.ts';\nimport { currentEnvironment, setCityProvider } from './environment.ts';\nimport { createHttpRoute, registerHttpRoute } from './plugin/http-route.ts';\nimport { registerLifecycle } from './plugin/lifecycle.ts';\nimport { registerChatCommand } from './plugin/command-chat.ts';\nimport { registerPetCommand } from './plugin/command-pet.ts';\nimport { registerLoops } from './plugin/loops.ts';\nimport { registerBalanceCommand } from './plugin/command-balance.ts';\nimport { registerSessionWatch } from './plugin/session-watch.ts';\nimport { createDesktopHelper } from './plugin/desktop-helper.ts';\nimport { createBalancePoll } from './plugin/balance-poll.ts';\nimport { createChatMemory } from './plugin/chat-memory.ts';\nimport { generateChat } from './chat.ts';\nimport { ensurePowerContextMemory } from './memory/powercontext.ts';\nimport { createSessionNotify } from './plugin/session-notify.ts';\nimport { createPetLookup } from './plugin/pet-lookup.ts';\nimport { createDownloadReport } from './plugin/download-report.ts';\nimport { createWorkStatusBridge } from './plugin/work-status-bridge.ts';\nimport { registerTodoReminders } from './plugin/todo-reminders.ts';\nimport { DEEPSEEK_OFFICIAL_PROVIDER_ID } from './balance/providers/deepseek-official.ts';\nimport { ensureDeepseekAsrProvider } from './voice/builtin-deepseek-asr.ts';\nimport { ensureDeepseekTtsProvider } from './voice/builtin-deepseek-tts.ts';\nimport { ensureDshSpeechProvider } from './voice/builtin-dsh.ts';\nimport { ensureEdgeProvider } from './voice/builtin-edge.ts';\nimport { credentialRef } from '@deepseek-ai/dsh-credentials';\nimport { createVoiceService } from './voice/speak.ts';\nimport { createHearService } from './voice/hear.ts';\nimport { listChatMemoryProviders } from './chat-memory-provider.ts';\nimport { TODO_FILE_NAME, TodoStore } from './todo/store.ts';\nimport { join } from 'node:path';\nimport type { PetRouteDeps } from './routes/types.ts';\n\n/** 插件行 id（与 cordis.patch.yml 一致） */\nexport const name = 'pet';\n/** 需要注入的服务：webServer（路由）+ agentDefaultModel（当前服务商）+ credentials（凭证）+ llm（对话模型调用）+ commands（/balance 斜杠命令）+ connection（桌面 Helper「打开 AI 设置」用的已鉴权站点 URL） */\nexport const inject = ['webServer', 'agentDefaultModel', 'credentials', 'llm', 'commands', 'connection'];\n\n/** 检索查询的改写提示词：结合最近几轮还原指代，只要一条能拿去检索的查询，不要解释、不要多行。 */\nconst REWRITE_QUERY_SYSTEM =\n  '把用户这句话改写成一条用于检索长期记忆的查询：结合最近几轮对话还原「它」「那个」「继续」这类指代，保留检索需要的名词与限定词，去掉寒暄、语气词与称呼，不要解释、不要引号、不要换行。只输出这条查询本身。';\n\n/** 宿主插件主体：注册 `/dsh-pet-7340` 前缀路由与斜杠命令（/balance /pet /chat）；ctx 暂用 any（peer 类型包本地不可解析）。 */\n// eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入的 ctx（webServer/locale 等 service 无静态类型）\nexport function apply(ctx: any): void {\n  const setup = createHostSetup(ctx);\n  const {\n    userRoot,\n    log,\n    configPaths,\n    thumbUserRoot,\n    memeDirsFor,\n    standaloneAiPolicy,\n    standaloneAiBalance,\n    state,\n    playback,\n    workStatus,\n    EXTERNAL_WORK_SESSION,\n    nextExternalWorkSeq,\n  } = setup;\n  const workStatusBridge = createWorkStatusBridge({ state, workStatus, EXTERNAL_WORK_SESSION });\n  const { publishWorkStatus, stopWorkStatusFlush } = workStatusBridge;\n  const downloadReport = createDownloadReport({\n    EXTERNAL_WORK_SESSION,\n    nextExternalWorkSeq,\n    publishWorkStatus,\n    workStatus,\n  });\n  const { reportDownload, stopDownloadSlotTimer } = downloadReport;\n  const petLookup = createPetLookup({ state, configPaths });\n  const { lock, sleep, sleepRefusalText } = petLookup;\n  const sessionNotify = createSessionNotify({ ctx, publishWorkStatus, state, workStatus });\n  const {\n    pushNotifyFrame,\n    turnFlags,\n    terminalTimers,\n    lastTodoText,\n    lastReplyText,\n    toolsInFlight,\n    cancelTerminalCleanup,\n    scheduleTerminalCleanup,\n    notifyActivityTimers,\n    scheduleCompletionNotify,\n  } = sessionNotify;\n  // 天气城市覆盖：配置里写了就按它查，不再由 IP 归属地库决定。\n  // 只注入这一次——/environment 路由与 system 时间行调的是同一个 currentEnvironment，\n  // 各自再去读配置就会出现「气泡说扬州、碎碎念说南京」。\n  setCityProvider(() => {\n    const city = readAllConfig(configPaths).main?.environmentCity;\n    return typeof city === 'string' && city.trim() !== '' ? city.trim() : undefined;\n  });\n  const chatMemory = createChatMemory({ ctx, configPaths, log, memeDirsFor, playback, state, userRoot });\n  const { lastWhisperAt, publishWhisper, publishSleepTalk, chatWithPet, getActivePetId, setActivePetId } = chatMemory;\n\n  const balancePoll = createBalancePoll({ ctx, configPaths, getActivePetId, log, state, standaloneAiBalance });\n  const { effectivePetList, balancePeriodSec, whisperPeriodSec, refreshBalance, resolveActivePetId, petDisplayName } =\n    balancePoll;\n\n  // 待办清单：一份用户级数据（不分宠物），落盘在插件数据根；提醒循环与 /todos 路由共用同一个实例。\n  const todos = new TodoStore({ file: join(userRoot, TODO_FILE_NAME), log });\n\n  const desktopHelper = createDesktopHelper({\n    ctx,\n    configPaths,\n    effectivePetList,\n    log,\n    reportDownload,\n    thumbUserRoot,\n    // 惰性取用：handlePetRoute 在下方装配，Helper 只在启动/收请求时才真正调用它\n    getHandlePetRoute: () => httpRoute.handlePetRoute,\n  });\n  const { startHelper, stopHelper, markDisposed } = desktopHelper;\n\n  // 内置语音实现与第三方走同一条注册路径：先登记，两个服务才解析得到各自的实现。\n  // 识别那侧惰性依赖宿主服务，没装语音输入插件也能登记——调用时才回 unsupported。\n  ensureEdgeProvider();\n  ensureDshSpeechProvider({ speechToText: () => setup.optionalService('speechToText') });\n  // DeepSeek 官方语音：鉴权复用 DSH 的 DEEPSEEK_API_KEY，与余额那条路一致；\n  // 独立模式依次借「语音专用 key」和「余额选 DeepSeek 时的那把」，最后才回落 DSH 凭据\n  const resolveDeepseekKey = async (): Promise<string | undefined> => {\n    const dedicated = setup.standaloneDeepseekKey();\n    if (dedicated) return dedicated;\n    const standalone = setup.standaloneAiBalance();\n    if (standalone?.provider === DEEPSEEK_OFFICIAL_PROVIDER_ID && standalone.apiKey) return standalone.apiKey;\n    const resolved = await ctx.credentials.resolve(credentialRef('DEEPSEEK_API_KEY'));\n    return resolved?.value;\n  };\n  ensureDeepseekTtsProvider({ resolveKey: resolveDeepseekKey });\n  ensureDeepseekAsrProvider({ resolveKey: resolveDeepseekKey });\n\n  /** 读配置里的长期记忆段：每次现读，改完配置不必重启。 */\n  const memoryBlock = (): Record<string, unknown> => {\n    const block = readAllConfig(configPaths).main?.memory;\n    return block && typeof block === 'object' ? (block as Record<string, unknown>) : {};\n  };\n  /** 读 `memory.powercontext` 里的一项；缺段或类型不对回默认。 */\n  const powerContextField = (key: 'endpoint' | 'token'): string => {\n    const conf = memoryBlock().powercontext;\n    if (!conf || typeof conf !== 'object') return '';\n    const value = (conf as Record<string, unknown>)[key];\n    return typeof value === 'string' ? value : '';\n  };\n  // 长期记忆：PowerContext 是本机自建服务，地址与令牌来自配置。\n  // 查询优化默认关闭——指代指向的通常是刚说过的话，那些轮次本来就在对话历史里；\n  // 打开后才复用对话模型改写（空配图池加空动作名单 = 纯文本生成，不注入指令也不解析动作），并带上最近两轮。\n  ensurePowerContextMemory({\n    endpoint: () => powerContextField('endpoint'),\n    token: () => powerContextField('token'),\n    rewrite: async ({ userText, history }) => {\n      const conf = memoryBlock().powercontext;\n      const enabled = conf && typeof conf === 'object' && (conf as Record<string, unknown>).optimizeQuery === true;\n      if (!enabled) return undefined;\n      const result = await generateChat({\n        ctx,\n        system: REWRITE_QUERY_SYSTEM,\n        history,\n        userText,\n        pool: [],\n        actions: [],\n      });\n      return result.ok ? result.text : undefined;\n    },\n  });\n\n  const deps: PetRouteDeps = {\n    ...setup,\n    ...petLookup,\n    ...workStatusBridge,\n    ...chatMemory,\n    ...balancePoll,\n    ...desktopHelper,\n    ...sessionNotify,\n    ctx,\n    todos,\n    // 环境查询：/environment 与 system 时间行共用同一个取数口。\n    // 传了 city 就照传（空串 = 忽略配置、按 IP 定位，设置页「检测」走这条）；\n    // 没传则交回 currentEnvironment 里注入的读取口。\n    environment: (opts?: { fresh?: boolean; city?: string }) =>\n      currentEnvironment({\n        force: opts?.fresh === true,\n        ...(opts?.city === undefined ? {} : { city: opts.city }),\n      }),\n    // 语音合成：缓存落 userRoot，失败只留日志，不打断宿主。\n    // 请求没带音色时用配置里的那个值——代码里没有第二份默认音色。\n    voice: createVoiceService({\n      userRoot,\n      log,\n      configuredVoice: () => {\n        const name = readAllConfig(configPaths).main?.voiceName;\n        return typeof name === 'string' && name ? name : undefined;\n      },\n    }),\n    // 语音识别：实现来自注册表；请求没带 provider 时用配置里的那个值，没有第二份默认\n    speech: createHearService({\n      configuredProvider: () => {\n        const provider = readAllConfig(configPaths).main?.speechProvider;\n        return typeof provider === 'string' && provider ? provider : undefined;\n      },\n    }),\n    // 长期记忆实现目录：设置页据此渲染下拉，配置项 memoryProvider 的取值就来自它\n    memory: { list: listChatMemoryProviders },\n  };\n  const httpRoute = createHttpRoute(deps);\n  registerHttpRoute(ctx, httpRoute.handlePetRoute);\n\n  registerSessionWatch({\n    ctx,\n    cancelTerminalCleanup,\n    lastTodoText,\n    lastReplyText,\n    notifyActivityTimers,\n    publishWorkStatus,\n    pushNotifyFrame,\n    scheduleCompletionNotify,\n    scheduleTerminalCleanup,\n    terminalTimers,\n    toolsInFlight,\n    turnFlags,\n    workStatus,\n  });\n\n  registerBalanceCommand({ ctx, effectivePetList, refreshBalance, sleep, sleepRefusalText });\n\n  registerLoops({\n    ctx,\n    balancePeriodSec,\n    configPaths,\n    lastWhisperAt,\n    lock,\n    log,\n    publishWhisper,\n    publishSleepTalk,\n    refreshBalance,\n    sleep,\n    standaloneAiPolicy,\n    whisperPeriodSec,\n  });\n\n  registerPetCommand({ ctx, effectivePetList, petDisplayName, resolveActivePetId, setActivePetId });\n\n  registerChatCommand({ ctx, chatWithPet, log, publishWhisper, resolveActivePetId, sleep, sleepRefusalText });\n\n  // 待办提醒：随插件生命周期起停；锁被第三方持有时由 pickReminderSpeaker 跳过该宠物。\n  // 播报开关现读现用：改配置后下一次提醒即生效，不必重启。\n  registerTodoReminders({\n    ctx,\n    effectivePetList,\n    isVoiceTodoEnabled: () => readAllConfig(configPaths).main?.voiceTodoEnabled === true,\n    lock,\n    log,\n    sleep,\n    state,\n    todos,\n    waiterCount: () => state.waiterCount(),\n  });\n\n  registerLifecycle({\n    ctx,\n    lock,\n    markDisposed,\n    playback,\n    state,\n    stopDownloadSlotTimer,\n    stopHelper,\n    stopWorkStatusFlush,\n  });\n\n  // 路由就绪后拉起桌面 Helper（Electron 缺失时仅告警，不影响 DSH 与浏览器 overlay）\n  startHelper();\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/session-watch.ts",
      "content": "/**\n * 会话事件监听：把 DSH 的 session/event 折叠成工作状态与完成通知。\n *\n * 不决定通知文案与档位（归 notify-events 与 shared/work-status），只做事件到判定的转接。\n * @module dsh-pet/src/host/plugin/session-watch\n */\nimport { GOAL_UPDATE_TOOL, currentTaskFromTodo, goalUpdateAction, reduceWorkStatus } from '../work-status.ts';\nimport { toolDetailFromEvent } from '../tool-detail.ts';\nimport {\n  agentErrorFrame,\n  lastAssistantText,\n  isCompletionTurnEnd,\n  reduceNotifyFrame,\n  sessionIdOf,\n  shouldNotifySession,\n  withSessionId,\n} from '../notify-events.ts';\nimport type { SessionNotify, ToolCallKey, ToolCallLedger } from './session-notify.ts';\nimport type { WorkStatusBridge } from './work-status-bridge.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 会话事件监听的输入。 */\nexport type SessionWatchInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<SessionNotify, 'cancelTerminalCleanup'> &\n  Pick<SessionNotify, 'lastTodoText'> &\n  Pick<SessionNotify, 'lastReplyText'> &\n  Pick<SessionNotify, 'notifyActivityTimers'> &\n  Pick<WorkStatusBridge, 'publishWorkStatus'> &\n  Pick<SessionNotify, 'pushNotifyFrame'> &\n  Pick<SessionNotify, 'scheduleCompletionNotify'> &\n  Pick<SessionNotify, 'scheduleTerminalCleanup'> &\n  Pick<SessionNotify, 'terminalTimers'> &\n  Pick<SessionNotify, 'toolsInFlight'> &\n  Pick<SessionNotify, 'turnFlags'> &\n  Pick<HostSetup, 'workStatus'>;\n\n/** 一次工具事件在记账表里的形态：调用开始（带详情）或结果返回（按标识移除一条）。 */\ntype ToolPhase =\n  | { kind: 'call'; detail: string; callId: ToolCallKey | undefined }\n  | { kind: 'result'; callId: ToolCallKey | undefined };\n\n/** 记账之后气泡的去向。 */\ntype ToolPhaseOutcome = {\n  /** 要写进气泡的文案；`undefined` = 本次不改文案，`null` = 清空回落到档位文案。 */\n  task?: string | null;\n  /** 是否还有带描述的操作在跑：为真时把档位压回 working，避免结果档盖住没干完的活。 */\n  keepWorking: boolean;\n};\n\n/** 记账所需的一次工具事件输入。 */\ntype TrackInput = {\n  /** 事件类型，只有 `tool/call` 与 `tool/result` 会进记账表。 */\n  type: string;\n  /** 本次事件的调用标识；缺失时由记账层用临时 Symbol 占位。 */\n  callId: ToolCallKey | undefined;\n  /** `tool/call` 的详情文案；`null` 表示这次调用没有可展示的描述。 */\n  detail: string | null;\n  /** 该会话最近一条 todo 文案，表清空后回落到它。 */\n  lastTodo: string | null;\n};\n\n/**\n * 取本次工具事件的调用标识。\n *\n * `tool/call` 的标识在 `data.callId`，`tool/result` 在 `data.message.source.callId`\n * （`ToolResultMessage.source` 由 `ToolMessageSource` 保证必带）。\n *\n * @returns 非空字符串标识；缺失或类型不对时 `undefined`，交给记账层用临时 Symbol 占位。\n */\nfunction toolCallIdOf(event: unknown): ToolCallKey | undefined {\n  const data = (event as { data?: { callId?: unknown; message?: { source?: { callId?: unknown } } } } | null)?.data;\n  const raw = data?.message?.source?.callId ?? data?.callId;\n  return typeof raw === 'string' && raw !== '' ? raw : undefined;\n}\n\n/**\n * 更新一个会话的在途调用表，算出气泡该显示什么。\n *\n * @param ledger - 每会话在途调用表；本函数原地修改。\n * @param sessionId - 会话标识。\n * @param phase - 本次是调用开始还是结果返回，以及对应的调用标识。\n * @param lastTodo - 表清空后回落到的 todo 文案。\n * @returns 气泡文案与是否仍在工作。\n */\nfunction trackToolPhase(\n  ledger: ToolCallLedger,\n  sessionId: string,\n  phase: ToolPhase,\n  lastTodo: string | null,\n): ToolPhaseOutcome {\n  if (phase.kind === 'call') {\n    let pending = ledger.get(sessionId);\n    if (!pending) ledger.set(sessionId, (pending = new Map()));\n    pending.set(phase.callId ?? Symbol(), phase.detail);\n    return { task: phase.detail, keepWorking: true };\n  }\n  const pending = ledger.get(sessionId);\n  // 缺标识的结果只释放一个匿名条目：不猜它是哪个具名调用，宁可少记一条也不删错别人的。\n  const key = phase.callId ?? [...(pending?.keys() ?? [])].find((id) => typeof id === 'symbol');\n  if (key !== undefined) pending?.delete(key);\n  const remaining = [...(pending?.values() ?? [])];\n  if (pending?.size === 0) ledger.delete(sessionId);\n  const active = remaining.pop();\n  if (active !== undefined) return { task: active, keepWorking: true };\n  return { task: lastTodo, keepWorking: false };\n}\n\n/**\n * 把一次工具事件落进记账表。\n *\n * @param ledger - 每会话在途调用表；本函数原地修改。\n * @param sessionId - 会话标识。\n * @param input - 事件类型、调用标识与详情文案。\n * @returns 记账结果；没有可展示详情且不是结果事件时返回 `undefined`（气泡不因它改文案）。\n */\nfunction trackToolEvent(ledger: ToolCallLedger, sessionId: string, input: TrackInput): ToolPhaseOutcome | undefined {\n  if (input.detail !== null) {\n    return trackToolPhase(\n      ledger,\n      sessionId,\n      { kind: 'call', detail: input.detail, callId: input.callId },\n      input.lastTodo,\n    );\n  }\n  if (input.type === 'tool/result') {\n    return trackToolPhase(ledger, sessionId, { kind: 'result', callId: input.callId }, input.lastTodo);\n  }\n  return undefined;\n}\n\n/** 注册会话事件监听；返回的清理函数由 ctx.effect 收集。 */\nexport function registerSessionWatch(deps: SessionWatchInput): void {\n  const {\n    ctx,\n    cancelTerminalCleanup,\n    lastTodoText,\n    lastReplyText,\n    notifyActivityTimers,\n    publishWorkStatus,\n    pushNotifyFrame,\n    scheduleCompletionNotify,\n    scheduleTerminalCleanup,\n    terminalTimers,\n    toolsInFlight,\n    turnFlags,\n    workStatus,\n  } = deps;\n  // 工作状态联动：监听 DSH 会话事件 → 聚合当前活动状态（WorkStatusStore → 展示快照）。\n  // 消费 turn/start、user/message（goal 续跑轮判定）、tool/call、tool/result、approval/asked、\n  // turn/end、todo/write（只更新任务详情文案，不切档位）。纯监听不调用模型。\n  ctx.effect(() => {\n    const dispose = ctx.on('session/event', (session: unknown, event: unknown) => {\n      const type = (event as { type?: string } | null)?.type;\n      if (!type) return;\n      const sessionId = String(\n        (session as { id?: unknown; header?: { id?: unknown } } | null)?.header?.id ??\n          (session as { id?: unknown } | null)?.id ??\n          'unknown',\n      );\n      if (type === 'todo/write') {\n        // 任务详情文案只写该会话的条目（state/task 同源，不可能串会话）。会话没有活动条目\n        // （已空闲/已清理）→ 不动：不会被展示，写进去只会成为一条幽灵文案。\n        // 清单里再无 in_progress/pending 时返回 null，气泡回落到档位文案。\n        const text = currentTaskFromTodo(event as { data?: { todos?: Array<{ status?: string; content?: string }> } });\n        // 缓存无条件更新：工具跑完要靠它把气泡恢复回来（见下方 tool/call 的接线）\n        lastTodoText.set(sessionId, text);\n        // 工具正在执行时不覆盖气泡：「修改 index.ts」比清单里那句更能说明此刻在动什么\n        if ((toolsInFlight.get(sessionId)?.size ?? 0) > 0) return;\n        if (workStatus.has(sessionId)) {\n          workStatus.setTask(sessionId, text);\n          publishWorkStatus(); // 任务文案变化也要写 S（气泡内容靠它更新）\n        }\n        return;\n      }\n      if (type === 'user/message') {\n        // 目标续跑轮判定：自动轮的消息带 source.kind==='goal'（round>0），该轮属自动续跑，\n        // 其 turn/end completed 只是「本轮完成」，不是整个任务完成\n        const source = (event as { data?: { source?: { kind?: string } } })?.data?.source;\n        if (source?.kind === 'goal') {\n          const flags = turnFlags.get(sessionId) ?? { goalRound: false, closing: null };\n          flags.goalRound = true;\n          turnFlags.set(sessionId, flags);\n        }\n        return; // user/message 不驱动档位动画\n      }\n      if (type === 'turn/start') {\n        turnFlags.set(sessionId, { goalRound: false, closing: null }); // 新一轮：清 turn 级标志\n        // 新一轮也开始新的任务上下文：清掉上一轮留下的任务详情文案（issue #59），否则它会一直挂着。\n        // 代价：goal 续跑这类多轮任务，每轮开头会回落一瞬档位文案，直到本轮（通常在开头几步内）\n        // 再写一次 todo 清单。\n        workStatus.setTask(sessionId, null);\n        lastTodoText.delete(sessionId); // 上一轮的清单文案，不该被下一轮的工具跑完时「恢复」回来\n        toolsInFlight.delete(sessionId); // 上一轮若有工具没等到 tool/result（被打断），别拖累这一轮\n        publishWorkStatus(); // 清掉上一轮任务文案也要写 S\n      }\n      if (\n        type === 'tool/call' &&\n        String((event as { data?: { name?: unknown } })?.data?.name ?? '') === GOAL_UPDATE_TOOL\n      ) {\n        // update_goal complete/blocked = 本轮是该目标的收尾轮，其 completed 才是真完成\n        const action = goalUpdateAction(String((event as { data?: { arguments?: unknown } })?.data?.arguments ?? ''));\n        if (action) {\n          const flags = turnFlags.get(sessionId) ?? { goalRound: false, closing: null };\n          flags.closing = action;\n          turnFlags.set(sessionId, flags);\n        }\n      }\n      let next = reduceWorkStatus(\n        event as { type?: string; data?: Record<string, unknown> & { reason?: { kind?: string } } },\n        turnFlags.get(sessionId),\n      );\n      if (!next) {\n        // turn/end 的 null（aborted / blocked / 未知 kind）＝该会话回合已结束：清掉会话状态，让展示回到空闲或\n        // 落到其他活跃会话，防止回合被打断后永久卡在上一档；其他事件的 null 是「不关心」，忽略。\n        if (type === 'turn/end') {\n          turnFlags.delete(sessionId);\n          cancelTerminalCleanup(sessionId); // 条目都要清了，别留一个到点后无事可做的定时器\n          lastTodoText.delete(sessionId); // 按会话记的两份缓存跟着会话一起消失（防泄漏）\n          toolsInFlight.delete(sessionId);\n          workStatus.clear(sessionId); // 条目连同任务详情文案一起消失（clear 内部会重算展示）\n          publishWorkStatus(); // 回合被打断 → 回到空闲：前端据此收起常驻气泡\n        }\n        return;\n      }\n      const seq = Number((event as { seq?: unknown }).seq ?? 0);\n      // 工具详情（「修改 index.ts」这类具体描述）：比通用档位文案有用得多，workStatusEnabled\n      // 的宠物直接把它当气泡文本。\n      // 必须在 setState 之后写：setTask 要求会话条目已存在，而条目正是 setState 建出来的——\n      // 顺序反了这一句会被静默丢弃（不报错，最难查的那种）。\n      const detail =\n        type === 'tool/call' ? toolDetailFromEvent(event as { data?: { name?: unknown; arguments?: unknown } }) : null;\n      const outcome = trackToolEvent(toolsInFlight, sessionId, {\n        type,\n        callId: toolCallIdOf(event),\n        detail,\n        lastTodo: lastTodoText.get(sessionId) ?? null,\n      });\n      // 还有操作没完就把档位压回 working：结果档与「仍在执行」的文案同时出现会自相矛盾。\n      if (outcome?.keepWorking) next = 'working';\n      const changed = workStatus.setState(sessionId, next, seq);\n      if (outcome?.task !== undefined) workStatus.setTask(sessionId, outcome.task);\n      publishWorkStatus(); // 档位或文案变了 → 写 S（内容没变时它自己会短路，不产生多余写入）\n      // 同会话同状态不重复更新（防刷屏）：写已经落定，这里只负责跳过终态清理的重排\n      if (!changed) return;\n      // 终态只展示短暂窗口后自动清理：陈旧完成态不再浮上来（Bug 3 的一环，顺带缓解 Bug 2 残留）。\n      // 回到非终态则取消那次待执行的清理——否则它到点时会话已非终态，既不清也不重排，\n      // 条目（连同旧任务文案）就永久留下了。\n      if (next === 'success' || next === 'error') scheduleTerminalCleanup(sessionId);\n      else cancelTerminalCleanup(sessionId);\n    });\n    return () => {\n      dispose();\n      for (const t of terminalTimers.values()) clearTimeout(t);\n      terminalTimers.clear();\n    };\n  }, 'dsh-pet: work-status session events');\n\n  // 系统通知：监听 DSH 宿主事件生成通知帧入队，浏览器轮询 /state 读到后弹 toast（帧契约与\n  // shared/notify.ts 一致）。事件源：turn/end、approval/asked、tool/call（ask_user_question）、\n  // agent/error。两道门：会话门（子代理/委派不发）+ 活动门（只拦「对话完成」，延迟确认没活了再弹）。\n  // 纯监听不调用模型；通知是网页端能力，桌面模式不消费。\n  ctx.effect(() => {\n    const sessionDispose = ctx.on(\n      'session/event',\n      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- session/event 载荷无公开类型，any 只用于接收，函数内立刻交给 shouldNotifySession / reduceNotifyFrame 推导\n      (session: any, event: any) => {\n        // 会话门（issue #82）：子代理 / 委派会话不发通知——你等的是父对话，不是某一路子代理跑完。\n        // 判据用 header.origin（不是 parentSession，那会把普通 fork 的主对话一起静音），\n        // 判据不可用时放行，绝不把通知整体打哑。详见 notify-events.ts 的 shouldNotifySession。\n        if (!shouldNotifySession(session)) return;\n        // 回复正文来源：只记最近一段 assistant 文本，供完成通知的正文使用。取不到就不记，\n        // 下游回落空正文（宁可少一行字，也不能让通知整体失效）。\n        if (event?.type === 'assistant/message') {\n          const text = lastAssistantText(event as { type?: string; data?: Record<string, unknown> });\n          if (text) lastReplyText.set(sessionIdOf(session), text);\n        }\n        // 活动门（issue #114）：「对话完成」延迟确认这条会话确实没活了再弹——团队会话里 Lead 的\n        // 这一轮结束 ≠ 团队收工，成员还在跑时弹「对话完成」是误报。生成失败/输出截断、权限申请、\n        // 用户选择不过这道门，直接放行（理由见 notify-events.ts 的 isCompletionTurnEnd）。\n        if (isCompletionTurnEnd(event)) {\n          scheduleCompletionNotify(sessionIdOf(session), event);\n          return;\n        }\n        // 非完成收尾（出错 / 输出截断 / 中止）用不到这段正文，一并清掉，免得留到下一次完成。\n        if (event?.type === 'turn/end') lastReplyText.delete(sessionIdOf(session));\n        const frame = reduceNotifyFrame(event as Parameters<typeof reduceNotifyFrame>[0]);\n        // 帧带上「这条通知是哪条会话发出的」：点击时网页据此跳到那条会话（见 withSessionId）\n        if (frame) pushNotifyFrame(withSessionId(frame, sessionIdOf(session)));\n      },\n    );\n    // agent/error（agent-loop dispatch.emit）：无回合位置的生成失败；0.1.5 新增，\n    // 低版本 DSH 无此事件 = 少一条通知（turn/end error 分支已覆盖大部分失败场景），不报错。\n    // 两道门都管不到它：载荷只有 { turn, step, error }，不带会话标识，无从判定来源。\n    const errorDispose = ctx.on(\n      'agent/error',\n      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- agent/error 载荷无公开类型，且低版本 DSH 可能不带 error 字段，只能 any 后按可选链取 payload?.error\n      (payload: any) => {\n        pushNotifyFrame(agentErrorFrame(payload?.error));\n      },\n    );\n    return () => {\n      // 卸载时清掉待查的定时器：否则插件已卸载，到点还去写一次 S\n      for (const t of notifyActivityTimers.values()) clearTimeout(t);\n      notifyActivityTimers.clear();\n      sessionDispose();\n      errorDispose();\n    };\n  }, 'dsh-pet: notify frames');\n}\n"
    },
    {
      "path": "dsh-pet/src/client/notify.ts",
      "content": "/**\n * 系统通知引擎（浏览器半侧）：消费宿主生成的通知帧，按「聚焦不弹」发系统级 toast；\n * `main.notifyWhenFocused` 打开时不再做这道判断。\n * 这是独立于宠物的能力，只随 DSH 网页端走——桌面模式不做宠物无关的功能。\n * 不负责产生帧：宿主监听 DSH 事件并写进 `/state`，容器统一轮询发现 counter 变化后调 `notifyFromFrame`；\n * 中断 / 活动门等过滤也已在宿主侧完成。\n * 依赖 shared/notify.ts 的帧到文案映射、成品配置的 `main.notificationsEnabled` 总开关，\n * 以及 app.ts 注入的会话跳转与命名服务（取不到时只降级，不影响弹窗）。\n * @module dsh-pet/src/client/notify\n */\n\nimport { frameToToast, truncate, NOTIFY_ICONS as ICON_NAMES, type NotifyFrame } from '../shared/notify.ts';\nimport { ROUTE_PATH } from '../shared/constants.ts';\n\nlet pageVisible = typeof document !== 'undefined' && !document.hidden;\nlet pageFocused = typeof document !== 'undefined' && document.hasFocus();\n\nfunction refreshVisible(): void {\n  pageVisible = !document.hidden;\n}\nfunction refreshFocused(): void {\n  pageFocused = document.hasFocus();\n}\n\n/** 注册聚焦与可见性监听，返回解绑函数。 */\nfunction initFocusTracking(): () => void {\n  if (typeof document === 'undefined') return () => {};\n  document.addEventListener('visibilitychange', refreshVisible);\n  window.addEventListener('focus', refreshFocused);\n  window.addEventListener('blur', refreshFocused);\n  return () => {\n    document.removeEventListener('visibilitychange', refreshVisible);\n    window.removeEventListener('focus', refreshFocused);\n    window.removeEventListener('blur', refreshFocused);\n  };\n}\n\n/** 用户是否在看本页（页面可见且持有焦点）。\n *  系统通知与工作状态播报共用这一条：用户在看就不打扰，走开了才提醒。\n *  {@link isNotifyWhenFocused} 打开时调用方不再走这条路。 */\nexport function isPageActive(): boolean {\n  return pageVisible && pageFocused;\n}\n\n/**\n * 这一次要不要提醒。\n *\n * 总开关由调用方先判（系统通知与工作状态播报各有一个）；这里只回答「前台提醒」这一层：\n * 打开就提醒，关闭时只在用户走开 / 页面不可见时才提醒。\n *\n * @param whenFocused - 成品配置的 `main.notifyWhenFocused`。\n * @param pageActive - 用户是否正看着本页（{@link isPageActive}）。\n * @returns 该提醒时为 true。\n */\nexport function shouldRemind(whenFocused: boolean, pageActive: boolean): boolean {\n  return whenFocused || !pageActive;\n}\n\n/** 图标 URL；pic 路由由宿主提供（`assets/pic` → `/dsh-pet-7340/pic/<file>`）。 */\nconst PIC = (name: string): string => `${ROUTE_PATH}/pic/${name}.png`;\n\n/** 图标 URL 表；文件名以 shared 为单一来源，设置页的测试通知也用它。 */\nexport const NOTIFY_ICONS = {\n  done: PIC(ICON_NAMES.done),\n  error: PIC(ICON_NAMES.error),\n  truncated: PIC(ICON_NAMES.truncated),\n  approval: PIC(ICON_NAMES.approval),\n  question: PIC(ICON_NAMES.question),\n  test: PIC(ICON_NAMES.test),\n} as const;\n\n/** 当前生效的总开关；运行中可被 reloadNotifications 更新，设置页保存后即时生效。 */\nlet notifyEnabled = true;\n\n/** 前台聚焦时是否也提醒；同样由 reloadNotifications 更新，缺键按 false。 */\nlet notifyWhenFocused = false;\n\n/** 前台聚焦时是否也提醒；系统通知与工作状态播报共用这一条。 */\nexport function isNotifyWhenFocused(): boolean {\n  return notifyWhenFocused;\n}\n\n/** 会话跳转与命名：由 app.ts 注入，取不到服务时退化为不跳会话、不认会话名。 */\nexport interface SessionNavigator {\n  openSession(sessionId: string): void;\n  /** 该会话的显示名（通知标题用）；没有名字、会话不在列表里或取不到时返回 undefined。 */\n  sessionTitle?(sessionId: string): string | undefined;\n}\n\n/** 当前生效的会话跳转器（app.ts 注入；旧版 DSH 没有 uiWorkspace 时为 undefined）。 */\nlet sessionNavigator: SessionNavigator | undefined;\n\n/**\n * 取某条会话的显示名（通知标题用）。\n *\n * @param navigator - app.ts 注入的会话服务；旧版 DSH 可能整个缺失。\n * @param sessionId - 帧携带的会话 id；缺失时连查询都不做。\n * @returns 会话名；没有注入器、服务没有该能力或查询抛错时返回 undefined，调用方回落固定文案。\n */\nexport function sessionTitleFrom(\n  navigator: SessionNavigator | undefined,\n  sessionId: string | undefined,\n): string | undefined {\n  if (sessionId === undefined) return undefined;\n  try {\n    return navigator?.sessionTitle?.(sessionId);\n  } catch {\n    // 宿主 store 的 getSnapshot 在首屏列表仍 pending 时可能抛；取不到名字只回落标题，绝不能连累弹窗。\n    return undefined;\n  }\n}\n\n/**\n * 切到指定会话，并把窗口叫到前台。\n *\n * 先切会话再叫窗口，用户看到窗口的那一刻就是目标会话；`dsh://open` 只在 Electron 宿主里发，\n * 浏览器里导航该协议会弹拦截框。\n *\n * @param sessionId - 目标会话；缺省只尝试叫窗口。会话已删或服务缺失时静默跳过切换。\n */\nexport function jumpToSession(sessionId?: string): void {\n  if (sessionId !== undefined) {\n    // 跳转失败（会话已删 / 旧版没有该服务）绝不能连累「把窗口叫回来」那条腿。\n    try {\n      sessionNavigator?.openSession(sessionId);\n    } catch {\n      /* 不跳会话而已，继续叫窗口。 */\n    }\n  }\n  window.focus();\n  if (!/electron/i.test(navigator.userAgent)) return;\n  const frame = document.createElement('iframe');\n  frame.style.display = 'none';\n  frame.src = 'dsh://open';\n  document.body.append(frame);\n  setTimeout(() => frame.remove(), 1000);\n}\n\n/** 点通知：收起弹窗并跳到它指的那条会话（跳转细化见 {@link jumpToSession}）。 */\nexport function wireNotificationClick(n: Notification, sessionId?: string): void {\n  n.onclick = () => {\n    n.close();\n    jumpToSession(sessionId);\n  };\n}\n\n/** 发一条系统通知；总开关关闭、环境不支持、未授权或本页正在看时静默跳过。\n * 日志只在门之后记录：被拦下的触发不产生「弹窗」日志。 */\nfunction toast(title: string, body?: string, icon?: string, sessionId?: string): void {\n  if (!notifyEnabled) return;\n  // 开关关着时维持「聚焦不打扰」；打开后照常弹，不再看页面是否活跃。\n  if (!shouldRemind(notifyWhenFocused, isPageActive())) return;\n  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;\n  console.log('[dsh-pet] 【弹窗】' + title + (body ? '：' + body : ''));\n  try {\n    const opts: NotificationOptions = {};\n    if (body) opts.body = truncate(body);\n    if (icon) opts.icon = icon;\n    // 点击行为与真实事件通知共用 wireNotificationClick；图标加载失败只降级为无图标，不会关闭弹窗。\n    const n = new Notification(title, opts);\n    wireNotificationClick(n, sessionId);\n  } catch {\n    /* 个别桌面壳在构造时抛错：忽略，不打断业务。 */\n  }\n}\n\n/**\n * 帧 → toast 并发出；未知帧静默跳过，帧里的 sessionId 一并透传给点击行为。\n * 标题优先用会话名：同一个宿主上可以并行跑多条会话，通知里必须能认出是哪一条回来了。\n */\nfunction toastFrame(frame: NotifyFrame): void {\n  const sessionId = typeof frame.sessionId === 'string' ? frame.sessionId : undefined;\n  const t = frameToToast(frame, sessionTitleFrom(sessionNavigator, sessionId));\n  if (!t) return;\n  toast(t.title, t.body, PIC(t.icon), sessionId);\n}\n\n/** 申请通知权限的结果；失败时带原因与可选文案，供设置页红字展示。 */\nexport type PermissionResult =\n  { ok: true } | { ok: false; reason: 'unsupported' | 'denied' | 'rejected' | 'error'; message?: string };\n\n/**\n * 申请浏览器通知权限，必须在用户手势（点击）下调用，否则可能被静默压制。\n * 失败原因：`unsupported` 无 Notification、`denied` 已被阻止、`rejected` 询问时选了阻止、`error` 申请异常。\n */\nexport async function requestNotificationPermission(): Promise<PermissionResult> {\n  if (typeof Notification === 'undefined') return { ok: false, reason: 'unsupported' };\n  if (Notification.permission === 'granted') return { ok: true };\n  if (Notification.permission === 'denied') return { ok: false, reason: 'denied' };\n  try {\n    const p = await Notification.requestPermission();\n    if (p === 'granted') return { ok: true };\n    if (p === 'denied') return { ok: false, reason: 'rejected' };\n    // 弹窗被直接关掉 / 未选择：浏览器仍是 default。\n    return { ok: false, reason: 'error', message: '权限未授予（' + p + '）' };\n  } catch (e) {\n    return { ok: false, reason: 'error', message: e instanceof Error ? e.message : String(e) };\n  }\n}\n\n/** 读两个通知开关（成品配置 main 条目）；拉取或解析失败时按「总开关开启、不额外提醒」处理，不阻塞。 */\nasync function readNotifySettings(): Promise<{ enabled: boolean; whenFocused: boolean }> {\n  try {\n    const r = await fetch(ROUTE_PATH + '/config');\n    if (!r.ok) return { enabled: true, whenFocused: false };\n    const d = (await r.json().catch(() => null)) as { main?: Record<string, unknown> } | null;\n    const main = d?.main;\n    return {\n      enabled: typeof main?.notificationsEnabled === 'boolean' ? main.notificationsEnabled : true,\n      whenFocused: main?.notifyWhenFocused === true,\n    };\n  } catch {\n    return { enabled: true, whenFocused: false };\n  }\n}\n\n/** 重读两个开关（设置页保存开关后调用）；之后新触发的通知按新值执行，无需刷新页面。 */\nexport async function reloadNotifications(): Promise<void> {\n  const settings = await readNotifySettings();\n  notifyEnabled = settings.enabled;\n  notifyWhenFocused = settings.whenFocused;\n}\n\n/** 一帧通知 → toast；由容器统一轮询 `/state` 发现 `sections.notify` 变化后调用。 */\nexport function notifyFromFrame(frame: unknown): void {\n  toastFrame(frame as NotifyFrame);\n}\n\n/**\n * 初始化通知引擎：记住会话跳转器、读总开关、兜底申请权限并跟踪页面聚焦；不做轮询。\n * @param navigator - 会话跳转与命名服务；不传时点击只叫窗口、标题回落固定文案。\n * @returns 释放函数，摘掉聚焦监听。\n */\nexport function initNotify(navigator?: SessionNavigator): () => void {\n  sessionNavigator = navigator;\n  // 总开关读成品配置（拉取失败不阻塞，默认开启）；之后由设置页保存后 reloadNotifications 重读。\n  void readNotifySettings().then((settings) => {\n    notifyEnabled = settings.enabled;\n    notifyWhenFocused = settings.whenFocused;\n    if (typeof Notification !== 'undefined' && settings.enabled && Notification.permission === 'default') {\n      // 兜底申请；无手势时浏览器可能压制，真正的申请在设置页开关或按钮点击处。\n      void requestNotificationPermission();\n    }\n  });\n  return initFocusTracking();\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/http-route.ts",
      "content": "/**\n * 路由装配：把装配期对象收成 PetRouteDeps，接上领域路由，并把处理函数挂到 webServer。\n *\n * 路由层只认这个 deps 表，不认识 apply 的闭包；素材路径与协议细节归 ../http.ts。\n * 必须始终成立：HTTP 前缀路由与桌面 Helper 管道消费同一个 handlePetRoute（两端行为严格一致）。\n * @module dsh-pet/src/host/plugin/http-route\n */\nimport type { IncomingMessage, ServerResponse } from 'node:http';\nimport { ROUTE_SEGMENT } from '../../shared/constants.ts';\nimport { readBody, sendFile, sendJson, sendText, type RouteResult } from '../http.ts';\nimport { failureBody } from '../routes/result.ts';\nimport { createPetRouter } from '../routes/index.ts';\nimport type { PetRouteDeps } from '../routes/types.ts';\nimport type { HostContext } from './context.ts';\n\n/** 单次业务请求的处理函数：URL 已解析、方法已归一。 */\nexport type HttpRouteHandler = (\n  url: string,\n  method: string,\n  body?: string,\n  signal?: AbortSignal,\n) => Promise<RouteResult>;\n\n/**\n * 由依赖表构造 HTTP 处理函数。\n * @param deps - 路由层依赖（store、路径、动作函数）。\n * @returns 按前缀分发到领域路由的处理函数。\n */\nexport function createHttpRoute(deps: PetRouteDeps): { handlePetRoute: HttpRouteHandler } {\n  // 配置请求覆盖完整读改写：下一次更新必须读取前一次完成后的配置。\n  // GET /config 同样排队，避免写入尚未完成时读到空文件而回退内置默认。\n  let configQueue: Promise<void> = Promise.resolve();\n\n  /** 单次业务路由（HTTP 落盘与桌面 Helper 管道共用同一份实现）：输入 rawUrl + method + body 文本，\n   *  返回 RouteResult，消费方各自落盘——业务逻辑只有一份，两端天然一致。\n   *  signal 可选：调用方断开时中止挂起等待（只有 /playback 的 wait 分支会用到；管道侧不传）。 */\n  const handlePetRoute = async (\n    rawUrl: string,\n    method: string,\n    body?: string,\n    signal?: AbortSignal,\n  ): Promise<RouteResult> => {\n    const url = new URL(rawUrl, 'http://localhost');\n    const rest = decodeURIComponent(url.pathname.slice(ROUTE_SEGMENT.length + 1));\n    const run = (): Promise<RouteResult> => dispatchPetRoute(url, rest, method, body, signal);\n    // 写配置的三条路径（PUT/POST /config、POST /pet-display、POST /pet-config）都是「读当前配置\n    // → 白名单重建整段 pets → 写盘」，并发交错会互相覆盖，必须共用一条串行队列；\n    // GET /config 同样排队，避免写入尚未完成时读到空文件而回退内置默认。\n    const isConfigQueue = rest === 'config' || ((rest === 'pet-display' || rest === 'pet-config') && method === 'POST');\n    if (isConfigQueue) {\n      const pending = configQueue.then(run, run);\n      configQueue = pending.then(\n        () => undefined,\n        () => undefined,\n      );\n      return pending;\n    }\n    return run();\n  };\n\n  // 路由层依赖表：显式传参取代闭包捕获，各领域模块因此可独立演进（见 ./routes/index.ts）\n  const dispatchPetRoute = createPetRouter(deps);\n\n  return { handlePetRoute };\n}\n\n/**\n * 把前缀路由挂到宿主 webServer，随插件卸载自动摘除。\n * @param ctx - 宿主上下文。\n * @param handlePetRoute - 业务处理函数（桌面 Helper 管道复用同一个）。\n */\nexport function registerHttpRoute(ctx: HostContext, handlePetRoute: HttpRouteHandler): void {\n  ctx.effect(\n    () =>\n      ctx.webServer.register({\n        kind: 'prefix',\n        path: ROUTE_SEGMENT,\n        handler: async (req: IncomingMessage, res: ServerResponse) => {\n          // 挂起等待（/playback?wait=）期间调用方可能提前断开：据此中止等待，\n          // 否则那个等待者要一直留到超时才回收。'close' 在正常应答后也会触发，但那时监听已摘掉。\n          const abort = new AbortController();\n          const onClose = (): void => abort.abort();\n          res.on('close', onClose);\n          try {\n            // PATCH 也带体（待办的部分更新）；GET / DELETE 不读，避免无谓地等一个不会来的结束事件。\n            const readsBody = req.method === 'PUT' || req.method === 'POST' || req.method === 'PATCH';\n            const body = readsBody ? await readBody(req) : undefined;\n            const result = await handlePetRoute(req.url ?? '/', req.method ?? 'GET', body, abort.signal);\n            res.off('close', onClose);\n            if (result.kind === 'json') sendJson(res, result.status, result.obj, result.headers);\n            else if (result.kind === 'text') sendText(res, result.status, result.body);\n            else if (result.kind === 'none') {\n              /* 调用方已断开：不再写（写了会抛） */\n            } else sendFile(req, res, result.file, result.contentType); // 非 async：流在 open 后自己 pipe，错误内部收口\n          } catch (e) {\n            res.off('close', onClose);\n            // 连接已断（挂起等待被中止后也可能撞上）→ 不再写，避免二次抛错\n            if (!res.destroyed && !res.writableEnded) {\n              // 请求体超限与客户端中断是用户侧问题，不能报成 500；断连时连响应都写不出去。\n              const code = (e as { code?: string }).code;\n              if (code === 'body-too-large')\n                sendJson(res, 413, failureBody('payload-too-large', 'request body too large'));\n              else if (code !== 'client-aborted') {\n                // 未预期异常：真实原因只进日志，响应里只回分类文案（可能含绝对路径，不外泄）\n                ctx.logger?.warn?.(`[dsh-pet] route failed: ${e instanceof Error ? e.message : String(e)}`);\n                sendJson(res, 500, failureBody('internal-error', 'dsh-pet: internal error'));\n              }\n            }\n          }\n        },\n      }),\n    `dsh-pet: ${ROUTE_SEGMENT} asset route`,\n  );\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/lifecycle.ts",
      "content": "/**\n * 卸载清理：摘监听、停定时器、结束挂起等待，顺序不可调换。\n *\n * 不做启动（装配末尾单独 startHelper），不持有资源句柄。\n * @module dsh-pet/src/host/plugin/lifecycle\n */\nimport type { PetLookup } from './pet-lookup.ts';\nimport type { DesktopHelper } from './desktop-helper.ts';\nimport type { DownloadReport } from './download-report.ts';\nimport type { WorkStatusBridge } from './work-status-bridge.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 卸载清理的输入。 */\nexport type LifecycleInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<PetLookup, 'lock'> &\n  Pick<DesktopHelper, 'markDisposed'> &\n  Pick<HostSetup, 'playback'> &\n  Pick<HostSetup, 'state'> &\n  Pick<DownloadReport, 'stopDownloadSlotTimer'> &\n  Pick<DesktopHelper, 'stopHelper'> &\n  Pick<WorkStatusBridge, 'stopWorkStatusFlush'>;\n\n/** 注册卸载清理；返回的清理函数由 ctx.effect 收集。 */\nexport function registerLifecycle(deps: LifecycleInput): void {\n  const { ctx, lock, markDisposed, playback, state, stopDownloadSlotTimer, stopHelper, stopWorkStatusFlush } = deps;\n  // 随插件生命周期清理：桌面 Helper 回收（异步下载完成后不再拉起）+ 结束所有挂起的等待\n  // （回执与 /state 长轮询不结束的话，插件重载会留下一批悬挂响应，各自要等到超时才收尾）。\n  ctx.effect(() => () => {\n    markDisposed();\n    // 工作状态的补写定时器：卸载后它到点已经没有意义（叶子连同长轮询一起收尾），清掉免得挂着\n    stopWorkStatusFlush();\n    // 下载日志的「清槽」定时器：同上，卸载后它到点已经没有意义\n    stopDownloadSlotTimer();\n    // 占用锁：卸载时把锁全撤掉并写一次叶子——不写的话渲染端要等 TTL 到点才解除静止\n    // （写叶子必须在 state.cancelAll() 之前：那之后挂起的等待者已经收尾了）。\n    lock.releaseAll();\n    playback.cancelAll();\n    state.cancelAll();\n    stopHelper('dsh-host-stop');\n  });\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/chat-memory.ts",
      "content": "/**\n * 对话与记忆：读写记忆文件、串行化对话队列、维护活跃宠物并生成碎碎念与回复。\n *\n * 不拼人设（人设归配置），不发网络请求（归 ./chat、./whisper）。\n * 依赖由 apply 显式传入（见输入类型），模块内不读全局、不建单例。\n * @module dsh-pet/src/host/plugin/chat-memory\n */\nimport { join } from 'node:path';\nimport { generateChat, type ChatMemoryMessage } from '../chat.ts';\nimport { chatActionNames } from '../chat-action.ts';\nimport { currentEnvironment, type EnvironmentFacts } from '../environment.ts';\nimport { mkdir, readFile, writeFile } from 'node:fs/promises';\nimport { composeSystemPrompt, petPersona } from '../persona.ts';\nimport { festivalOf } from '../time-context.ts';\nimport { findPetInstance, readAllConfig, removeRoundsByTs, sliceMemoryRounds } from '../config.ts';\nimport type { PetImageRef } from '../image-attachment.ts';\nimport { limitPool, matchMeme, pickMeme, readMemePool, type MemeEntry } from '../memes.ts';\nimport { generateWhisper } from '../whisper.ts';\nimport { createMemoryOrphans } from './memory-orphans.ts';\nimport { configuredModel } from '../model-selection.ts';\nimport { SLEEP_TALK_INSTRUCTION } from '../whisper.ts';\nimport { pickVoiceSurface, type VoiceTarget } from '../surface.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\nimport {\n  DEFAULT_MEMORY_TIMEOUT_MS,\n  resolveChatMemoryProvider,\n  type CaptureTurn,\n  type ChatMemoryProvider,\n  type ChatRequest,\n  type ChatTurn,\n  type RecallRequest,\n} from '../chat-memory-provider.ts';\n\n/** 校验召回补丁里的历史项：形状不对的整段丢弃，避免坏数据把生成打崩。 */\nfunction isChatTurn(value: unknown): value is ChatTurn {\n  const turn = value as { role?: unknown; content?: unknown; ts?: unknown } | null;\n  return (\n    (turn?.role === 'user' || turn?.role === 'assistant') &&\n    typeof turn?.content === 'string' &&\n    typeof turn?.ts === 'number'\n  );\n}\n\n/** 校验召回返回的请求体：三个字段都得在，形状不对整份丢弃。 */\nfunction isChatRequest(value: unknown): value is ChatRequest {\n  if (!value || typeof value !== 'object') return false;\n  const body = value as { system?: unknown; history?: unknown; userText?: unknown };\n  return (\n    typeof body.system === 'string' &&\n    typeof body.userText === 'string' &&\n    Array.isArray(body.history) &&\n    body.history.every(isChatTurn)\n  );\n}\n\n/** 生成成功后的这一轮回复。 */\ninterface GeneratedTurn {\n  readonly text: string;\n  readonly image?: string;\n  readonly action?: string;\n}\n\n/** 一轮对话的只读上下文：读盘与纯计算的结果。 */\ninterface ChatContext {\n  readonly cfg: Record<string, Record<string, unknown>>;\n  readonly found: { conf: Record<string, unknown>; pet: Record<string, unknown>; entry: string };\n  readonly pool: MemeEntry[];\n  readonly actions: string[];\n  readonly list: ChatMemoryMessage[];\n  readonly system: string;\n}\n\n/** 这一句该由哪一端念：取宠物实例的 display 推导（桌面优先）；两端都不显示时为 `undefined`。 */\nfunction voiceTargetFor(pet: Record<string, unknown>): VoiceTarget | undefined {\n  return pickVoiceSurface(String(pet.display ?? '')) ?? undefined;\n}\n\n/** 对话与记忆的输入：装配期对象与更早的工厂。 */\nexport type ChatMemoryInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<HostSetup, 'configPaths'> &\n  Pick<HostSetup, 'log'> &\n  Pick<HostSetup, 'memeDirsFor'> &\n  Pick<HostSetup, 'playback'> &\n  Pick<HostSetup, 'state'> &\n  Pick<HostSetup, 'userRoot'>;\n\n/**\n * 创建对话与记忆。\n */\nexport function createChatMemory(deps: ChatMemoryInput) {\n  const { ctx, configPaths, log, memeDirsFor, playback, state, userRoot } = deps;\n  // 命令「当前桌宠」（/pet 选择、/chat 使用）：全局单值不分会话；进程内内存，重启回默认第一只\n  let activePetId = '';\n\n  // 碎碎念周期调度的「上次生成时刻」（按宠物）：调度拍据此判断到没到点。\n  // 生成结果直接写 S，多端共享同一句由 S 天然保证，不需要第二份缓存。\n  const lastWhisperAt = new Map<string, number>();\n\n  // 对话记忆文件（唯一读写方 = 本进程；浏览器/桌面两端都只是客户端 → 同一实例天然共享同一份记忆）。\n  // 结构双层：{ <种类桶 assetRoot ?? petId>: { <实例 id>: { messages: ChatMemoryMessage[] } } }\n  const memoryPath = join(userRoot, 'memory.json');\n\n  // 对话写操作串行队列：read-modify-write 排队执行，防两端同时对话时交错写盘\n  let chatQueue: Promise<void> = Promise.resolve();\n\n  /** 每只宠物的删除代数：对话开始时记下，写回前比对，变了说明生成期间历史被删过。 */\n  const deletedEpoch = new Map<string, number>();\n\n  /** 读记忆文件：不存在 → 空；解析失败/根不是对象 → 记日志 + 空记忆（不备份、不改写源文件） */\n  const readMemory = async (): Promise<Record<string, Record<string, { messages: ChatMemoryMessage[] }>>> => {\n    let raw: string;\n    try {\n      raw = await readFile(memoryPath, 'utf8');\n    } catch {\n      return {}; // 文件不存在 = 尚无记忆\n    }\n    try {\n      const parsed = JSON.parse(raw) as Record<string, unknown>;\n      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) throw new Error('not an object');\n      return parsed as Record<string, Record<string, { messages: ChatMemoryMessage[] }>>;\n    } catch (e) {\n      log.error(\n        `dsh-pet: 记忆文件无法解析（对话将从头开始）：${memoryPath}（${e instanceof Error ? e.message : String(e)}）`,\n      );\n      return {};\n    }\n  };\n\n  const writeMemory = async (mem: Record<string, Record<string, { messages: ChatMemoryMessage[] }>>): Promise<void> => {\n    await mkdir(userRoot, { recursive: true });\n    await writeFile(memoryPath, JSON.stringify(mem, null, 2), 'utf8');\n  };\n\n  /** 把一次读写封进串行队列（同进程内防交错），返回 fn 的结果 */\n  const withMemoryLock = <T>(fn: () => Promise<T>): Promise<T> => {\n    const run = chatQueue.then(fn, fn);\n    chatQueue = run.then(\n      () => undefined,\n      () => undefined,\n    );\n    return run;\n  };\n\n  /** 某宠物的最终人设 system：实例级 `pets[].whisperPrompt` 优先，没写回落到所属条目的那份。\n   *  拼装在 ./persona（纯函数）：人设正文 + 名字声明 + 一行时间背景，时间每次现算；\n   *  对话路径传 `{ historyTimes: true }` 追加【历史】说明，碎碎念没有历史，不传。\n   *  `env` 是城市与天气：对话、碎碎念、梦话都传——它们说的是同一只宠物此刻的处境。\n   *  收 `findPetInstance` 的命中结果而不是 (petId, cfg)：调用方都已解析过，再查只会多一处\n   *  「查不到就兜底 main」的不可达分支。 */\n  const petSystemPrompt = (\n    found: { conf: Record<string, unknown>; pet: Record<string, unknown> },\n    options: { historyTimes?: boolean; env?: EnvironmentFacts } = {},\n  ): string =>\n    composeSystemPrompt({\n      prompt: petPersona(found.conf, found.pet),\n      name: String(found.pet.name ?? ''),\n      id: String(found.pet.id ?? ''),\n      now: new Date(),\n      ...(options.historyTimes === true ? { historyTimes: true } : {}),\n      ...(options.env !== undefined ? { env: options.env } : {}),\n    });\n\n  /** 对话记忆轮数（1 轮 = 1 问 1 答）：该宠物所属条目的 chatMemoryRounds（合并器已填默认）。\n   *  收已解析的条目配置：调用方都已拿到 `findPetInstance` 的结果。 */\n  const memoryRounds = (conf: Record<string, unknown>): number => {\n    const v = Number(conf.chatMemoryRounds);\n    return Number.isFinite(v) && v >= 0 ? Math.floor(v) : 5;\n  };\n\n  /**\n   * 第三方召回：按 provider 声明的超时 abort，拿到整个请求体。\n   *\n   * 超时、抛错、返回形状非法一律按「本轮不介入」处理：只记日志，调用方用 `prepared` 继续。\n   *\n   * @param provider - 本轮生效的实现。\n   * @param req - 本轮输入与原始事实。\n   * @returns 可用的请求体；没有可用结果时 `undefined`。\n   */\n  const recallChat = async (provider: ChatMemoryProvider, req: RecallRequest): Promise<ChatRequest | undefined> => {\n    const recall = provider.recall;\n    if (!recall) return undefined;\n    // 竞速而不是只传 signal：provider 可以忽略 signal，核心不能因此挂住。\n    const signal = AbortSignal.timeout(provider.timeoutMs ?? DEFAULT_MEMORY_TIMEOUT_MS);\n    const deadline = new Promise<undefined>((resolve) => {\n      signal.addEventListener('abort', () => resolve(undefined), { once: true });\n    });\n    try {\n      const result = await Promise.race([Promise.resolve(recall.call(provider, req, signal)), deadline]);\n      if (result === undefined) return undefined;\n      if (!isChatRequest(result)) {\n        log.warn('[dsh-pet] 记忆召回返回非法请求体 id=' + provider.id);\n        return undefined;\n      }\n      return result;\n    } catch (error) {\n      log.warn(\n        '[dsh-pet] 记忆召回失败 id=' + provider.id + '：' + (error instanceof Error ? error.message : String(error)),\n      );\n      return undefined;\n    }\n  };\n\n  /**\n   * 落盘后接收这一轮问答：核心不等待，失败只记实现 id 与原因。\n   *\n   * @param provider - 本轮生效的实现；与召回同一个，避免写到别处。\n   * @param turn - 本轮问答与元信息；action/image 只是名字，不含素材本体。\n   */\n  const captureTurn = (provider: ChatMemoryProvider, turn: CaptureTurn): void => {\n    const capture = provider.capture;\n    if (!capture) return;\n    void Promise.resolve()\n      .then(() => capture.call(provider, turn))\n      .catch((error) => {\n        log.warn(\n          '[dsh-pet] 记忆接收失败 id=' + provider.id + '：' + (error instanceof Error ? error.message : String(error)),\n        );\n      });\n  };\n\n  /** 生成并返回某宠物的一句碎碎念（周期调度、菜单手动触发与命令行共用）：人设取它自己的 whisperPrompt，\n   *  没写回落到所属条目；成功写进 S 的 pets.<id>.say——碎碎念 / 命令气泡 / 对话回复在前端是同一条\n   *  展示链路，所以共用一个叶子。配图开关开启时从表情包池随机抽 1 张。\n   *  失败带回真实 reason（含 unknown-pet / unknown-image），成功带回生成的文本——调用方不必再拉一拍 /state。\n   *\n   *  @param petId - 目标宠物实例 id。\n   *  @param image - 指定配图的名称：给了就只用这张（不受 whisperImageEnabled 门控，手动点图是显式意图），\n   *  不在池内返回 unknown-image；缺省 = 按开关随机抽或纯文本。\n   *  @param voiceTo - 这一句该由哪一端念；缺省按它自己的 display 推导（桌面优先，见 {@link pickVoiceSurface}）。\n   *  路由层带 `?surface=` 的会显式传请求面，其余调用点留空即可。\n   *  @param kind - 这次生成的来源：`whisper` = 周期调度，受 `voiceWhisperEnabled` 管；`manual` = 菜单、\n   *  斜杠命令、路由主动触发，不看那个开关（用户主动点的就是这一句）。缺省 `manual`。\n   */\n  const publishWhisper = async (\n    petId: string,\n    image?: string,\n    voiceTo?: VoiceTarget,\n    kind: 'whisper' | 'manual' = 'manual',\n  ): Promise<\n    | { ok: true; text: string; image?: string }\n    | { ok: false; reason: 'provider-missing' | 'generate-error' | 'unknown-pet' | 'unknown-image'; message?: string }\n  > => {\n    const cfg = readAllConfig(configPaths);\n    const found = findPetInstance(cfg, petId);\n    // 宠物可能在「校验那次读」与这里之间被删（配置随时会变，两次读之间就是窗口）：\n    // 明确失败、不生成不写 S——写下去就是一只已不存在宠物的幽灵叶子（常驻到进程重启）。\n    if (!found) return { ok: false, reason: 'unknown-pet', message: '没有这只桌宠：' + petId };\n    // 每一类语音由自己的开关决定：周期调度看 voiceWhisperEnabled，手动触发（右键菜单、\n    // 斜杠命令）看 voiceEnabled。叶子不带 voiceTo = 谁都不念，气泡照旧弹。\n    const whisperVoiceOn = cfg.main?.voiceWhisperEnabled === true;\n    const manualVoiceOn = cfg.main?.voiceEnabled === true;\n    const voiceOff = kind === 'whisper' ? !whisperVoiceOn : !manualVoiceOn;\n    const target = voiceOff ? undefined : (voiceTo ?? voiceTargetFor(found.pet));\n    const system = petSystemPrompt(found, { env: await currentEnvironment() });\n    // 池只算一次：点名的图与随机抽图共用同一份（含文件存在性判定）。\n    const pool = readMemePool(found.conf.memes, memeDirsFor(found.entry));\n    // 点名了却没命中 = 配置写错或图已被删：明确失败，不静默换成另一张（点了 A 却看到 B 会以为坏了）。\n    const forced = image === undefined ? undefined : matchMeme(pool, image);\n    if (image !== undefined && forced === undefined) {\n      return { ok: false, reason: 'unknown-image', message: '表情包不在池内：' + image };\n    }\n    const meme = forced ?? (found.conf.whisperImageEnabled === true ? pickMeme(pool) : undefined);\n    // 模型：条目配置的 whisperModel 优先（留空 = 不指定）；生成侧失败会回落到当前对话的模型重试一次\n    const result = await generateWhisper(ctx, {\n      system,\n      meme,\n      preferred: configuredModel(found.conf, 'whisperModel'),\n    });\n    if (!result.ok) {\n      // 失败不写 S：静默跳过 + warn，不伪造文案、不弹错误气泡\n      log.warn(\n        '[dsh-pet] 碎碎念生成失败 pet=' +\n          petId +\n          ' reason=' +\n          result.reason +\n          (result.message ? ' ' + result.message : ''),\n      );\n      // 真实 reason 原样带回：路由若把失败硬编码成 generate-error，独立模式下已算出的\n      // provider-missing 就会在边界被吞掉（API.md 描述的降级 reason 正是它）。\n      return result;\n    }\n    state.writePet(petId, 'say', {\n      text: result.text,\n      ...(result.image ? { image: result.image } : {}),\n      ...(target ? { voiceTo: target } : {}),\n    });\n    // 成功也留一行：否则 logs.txt 里「没触发」与「触发了并且成功」无法区分。\n    log.info(\n      `[dsh-pet] 碎碎念生成成功 pet=${petId}，${result.text.length} 字` +\n        (result.image ? `，配图=${result.image}` : ''),\n    );\n    // 文本随返回值带出，且与刚写进叶子的是同一个变量：两条出口给同一份文本，不是一个真相两个版本\n    return { ok: true, text: result.text, ...(result.image ? { image: result.image } : {}) };\n  };\n\n  /** 生成并写一句梦话：system 只用人设，功能指令在 whisper（与碎碎念同属代码常量）；不配图、不念、不换动画。\n   *  睡着时「换动画」本身就是打扰，所以写 `say` 显式 `anim: false`，也不写 `voiceTo`。\n   *  @returns 是否真的生成并写进了 S；失败只留一行日志，调度下一拍再试。 */\n  const publishSleepTalk = async (petId: string): Promise<boolean> => {\n    const cfg = readAllConfig(configPaths);\n    const found = findPetInstance(cfg, petId);\n    if (!found) return false;\n    const system = petSystemPrompt(found, { env: await currentEnvironment() });\n    const result = await generateWhisper(ctx, {\n      system,\n      preferred: configuredModel(found.conf, 'whisperModel'),\n      instruction: SLEEP_TALK_INSTRUCTION,\n    });\n    if (!result.ok) {\n      log.warn(\n        '[dsh-pet] 梦话生成失败 pet=' +\n          petId +\n          ' reason=' +\n          result.reason +\n          (result.message ? ' ' + result.message : ''),\n      );\n      return false;\n    }\n    state.writePet(petId, 'say', { text: result.text, anim: false });\n    log.info(`[dsh-pet] 梦话生成成功 pet=${petId}，${result.text.length} 字`);\n    return true;\n  };\n\n  /** 读本轮上下文：配置、配图池、动作名、最近历史与人设。宠物不存在时返回 `null`。 */\n  const readContext = async (petId: string, env: EnvironmentFacts): Promise<ChatContext | null> => {\n    const cfg = readAllConfig(configPaths);\n    const found = findPetInstance(cfg, petId);\n    if (!found) return null;\n    // 配图：开关关闭 → 空池（指令与解析都不介入）；目录链按所属条目取。\n    // 张数上限（chatImageLimit，0 = 不限制）：整张清单每条消息都要附，截断后费用上限可控。\n    const pool =\n      found.conf.chatImageEnabled === true\n        ? limitPool(readMemePool(found.conf.memes, memeDirsFor(found.entry)), Number(found.conf.chatImageLimit))\n        : [];\n    // 动作名单：开关开启才取（关掉 = 不注入也不解析）；名单本身为空（没配 categories）同样等于关闭。\n    const actions = found.conf.chatAnimationEnabled === true ? chatActionNames(found.conf.animations) : [];\n    const mem = await readMemory();\n    const bucket = mem[found.entry];\n    const existing = bucket && typeof bucket === 'object' && !Array.isArray(bucket) ? bucket[petId] : undefined;\n    if (existing !== undefined && (!existing || !Array.isArray(existing.messages))) {\n      log.error(`[dsh-pet] 记忆结构异常（messages 不是数组）pet=${petId}，按新会话处理：${memoryPath}`);\n    }\n    // rounds = 0（用户关掉历史）→ 空历史；否则截尾部 rounds 轮（1 轮 = 1 问 1 答）。\n    // 不能写 slice(-rounds * 2)：-0 在 JS 里 === 0，slice(-0) 返回整个数组而不是空。\n    const list =\n      existing && Array.isArray(existing.messages)\n        ? sliceMemoryRounds(existing.messages, memoryRounds(found.conf))\n        : [];\n    // 人设：实例级 whisperPrompt 优先，没写回落所属条目（与碎碎念同一拼装）。\n    // 有历史才追加【历史】段：没有历史时那段话在描述不存在的前缀，只会误导模型。\n    const system = petSystemPrompt(found, { historyTimes: list.length > 0, env });\n    return { cfg, found, pool, actions, list, system };\n  };\n\n  /**\n   * 把这一轮写回 memory.json；生成期间历史被删过就整轮丢弃。\n   *\n   * @param args - 本轮问答、所属条目与开始时的删除代数。\n   * @returns 是否真的写入。\n   */\n  const writeTurn = (args: {\n    petId: string;\n    entryKey: string;\n    text: string;\n    reply: GeneratedTurn;\n    image?: PetImageRef;\n    ts: number;\n    epochAtStart: number;\n  }): Promise<boolean> =>\n    withMemoryLock(async () => {\n      if ((deletedEpoch.get(args.petId) ?? 0) !== args.epochAtStart) return false;\n      const mem = await readMemory();\n      // 坏结构（数组/标量）按空桶重建；messages 不是数组的条目按新会话处理，避免 push 到坏对象上崩溃\n      const bucket =\n        mem[args.entryKey] && typeof mem[args.entryKey] === 'object' && !Array.isArray(mem[args.entryKey])\n          ? mem[args.entryKey]\n          : (mem[args.entryKey] = {});\n      const existing = bucket[args.petId];\n      if (existing !== undefined && (!existing || !Array.isArray(existing.messages))) {\n        log.error(`[dsh-pet] 记忆结构异常（messages 不是数组）pet=${args.petId}，按新会话处理：${memoryPath}`);\n      }\n      const entry = existing && Array.isArray(existing.messages) ? existing : (bucket[args.petId] = { messages: [] });\n      // 用户上传的图只存不送：记忆要能还原「这一轮带过图」（聊天记录存档），但不把图本体重发给模型；\n      // AI 配的图只回填名称标记（见 chat.ts 的 historyMarkersOf），同样不带图本体。\n      entry.messages.push({\n        role: 'user',\n        content: args.text,\n        ts: args.ts,\n        ...(args.image ? { image: args.image } : {}),\n      });\n      entry.messages.push({\n        role: 'assistant',\n        content: args.reply.text,\n        ts: args.ts,\n        ...(args.reply.image ? { meme: args.reply.image } : {}),\n        // 动作名与配图名同类：落盘只存名字，回放历史时由 chat.ts 以 [动作:名] 回填——\n        // 否则模型记不得自己演过什么，用户说「换一个」它无从判断\n        ...(args.reply.action ? { action: args.reply.action } : {}),\n      });\n      await writeMemory(mem);\n      return true;\n    });\n\n  /** 与某只宠物对话：读上下文 → 召回 → 生成 → 写回 → 通知；生成期间历史被删则丢弃本轮写回。 */\n  const chatWithPet = async (\n    petId: string,\n    text: string,\n    image?: PetImageRef,\n  ): Promise<\n    | { ok: true; text: string; image?: string }\n    | { ok: false; reason: 'provider-missing' | 'generate-error' | 'unknown-pet'; message?: string }\n  > => {\n    // 环境（城市 + 天气）在锁外查：它是网络往返。\n    const env = await currentEnvironment();\n    const epochAtStart = deletedEpoch.get(petId) ?? 0;\n    // 读上下文只占一次短锁：召回与模型调用都在锁外。\n    const context = await withMemoryLock(() => readContext(petId, env));\n    if (context === null) return { ok: false, reason: 'unknown-pet', message: '没有这只桌宠：' + petId };\n    const { cfg, found, pool, actions, list, system } = context;\n    // 记忆实现：配置里的 id 决定用谁；未注册的 id 在解析时就回落内置，这里补一条日志说明。\n    const memoryConf = found.conf.memory;\n    const configuredId = String(\n      memoryConf && typeof memoryConf === 'object' ? ((memoryConf as Record<string, unknown>).provider ?? '') : '',\n    ).trim();\n    const provider = resolveChatMemoryProvider(configuredId);\n    if (configuredId !== '' && configuredId !== provider.id) {\n      log.warn('[dsh-pet] 记忆 provider 未注册：' + configuredId + '，本轮用 ' + provider.id);\n    }\n    // 图片只记尺寸与字节数（不记 base64）：模型不支持读图时 dsh-llm 会把它投影成占位文本，靠这行日志定位\n    if (image !== undefined) {\n      log.info(\n        `[dsh-pet] 对话附带图片 pet=${petId}，${image.width}x${image.height}，${image.bytes} 字节` +\n          '（模型不支持读图时内核会以占位文本代替）',\n      );\n    }\n    // 记忆：核心先拼一份完整请求体，provider 可整份替换，也可原样交回。\n    const prepared: ChatRequest = {\n      system,\n      history: list.map(({ role, content, ts }) => ({ role, content, ts })),\n      userText: text,\n    };\n    const festival = festivalOf(new Date());\n    const body =\n      (await recallChat(provider, {\n        petId,\n        userText: text,\n        prepared,\n        raw: {\n          persona: petPersona(found.conf, found.pet),\n          now: Date.now(),\n          env,\n          ...(festival === '' ? {} : { festival }),\n          memes: pool,\n          actions,\n          pet: {\n            id: String(found.pet.id ?? petId),\n            name: String(found.pet.name ?? ''),\n            entry: found.entry,\n            display: String(found.pet.display ?? ''),\n          },\n        },\n      })) ?? prepared;\n    // 模型：条目配置的 chatModel 优先（留空 = 不指定）；生成侧失败会回落到当前对话的模型重试一次\n    const generated = await generateChat({\n      ctx,\n      system: body.system,\n      history: body.history,\n      userText: body.userText,\n      pool,\n      actions,\n      preferred: configuredModel(found.conf, 'chatModel'),\n      image,\n    });\n    if (!generated.ok) return generated;\n    const now = Date.now();\n    // 写回再读一次拿最新内容，占一次短锁；生成期间历史被删过（代数变了）就整轮丢弃。\n    const persisted = await writeTurn({\n      petId,\n      entryKey: found.entry,\n      text,\n      reply: {\n        text: generated.text,\n        ...(generated.image !== undefined ? { image: generated.image } : {}),\n        ...(generated.action !== undefined ? { action: generated.action } : {}),\n      },\n      ...(image === undefined ? {} : { image }),\n      ts: now,\n      epochAtStart,\n    });\n    if (persisted) {\n      // 第三方记忆：落盘后异步接收；不等待、失败只记日志，不能影响这一轮回复。\n      captureTurn(provider, {\n        petId,\n        userText: text,\n        replyText: generated.text,\n        ts: now,\n        ...(generated.action !== undefined ? { action: generated.action } : {}),\n        ...(generated.image !== undefined ? { image: generated.image } : {}),\n      });\n    } else {\n      // 用户在生成期间删了历史：本轮不落盘、不通知第三方，回复照常返回。\n      log.info('[dsh-pet] 生成期间历史被删除，跳过写回与接收 pet=' + petId);\n    }\n    // 动作先写：与 POST /anim 同一条写回链路（记录 + anim 叶子），渲染端据此播放并回报执。\n    if (generated.action !== undefined) {\n      const record = playback.create(petId, generated.action);\n      state.writePet(petId, 'anim', { name: generated.action, playbackId: record.playbackId });\n    }\n    // 回复写进 S（与碎碎念同一个叶子：前端本来就是同一条展示链路）。\n    // 该由哪一端念按这只宠物的 display 推：对话请求带的是 surface=any，本来就没有具体的一端可用。\n    // 对话回复归「手动播报」：用户发了消息才有的这一句，由 voiceEnabled 决定念不念。\n    const replyVoiceTo = cfg.main?.voiceEnabled === true ? voiceTargetFor(found.pet) : undefined;\n    // 只有动作没有正文（模型只写了标记）→ 不写 say，避免弹一个空气泡。\n    if (generated.text !== '') {\n      state.writePet(petId, 'say', {\n        text: generated.text,\n        ...(generated.image ? { image: generated.image } : {}),\n        // 带动作时显式关掉碎碎念动画：气泡照弹，但不把刚点播的动作顶掉\n        ...(generated.action !== undefined ? { anim: false } : {}),\n        ...(replyVoiceTo ? { voiceTo: replyVoiceTo } : {}),\n      });\n    }\n    // 同一份文本随返回值带出（叶子照写，不是二选一）\n    return { ok: true as const, text: generated.text, ...(generated.image ? { image: generated.image } : {}) };\n  };\n\n  /** 删除某只宠物的对话记忆：`ts` 缺省 = 清空全部，给了 ts = 只删命中的轮（一轮两条共享 ts，成对删）。\n   *  与对话共用同一条串行队列；删除会推进该宠物的删除代数，正在生成的那一轮因此不再写回。\n   *  删空的宠物连叶子与空条目一起摘掉：否则 memory.json 里会永久堆着空对象，看不出这里曾有历史。 */\n  const deleteHistory = async (\n    petId: string,\n    ts?: readonly number[],\n  ): Promise<{ ok: true; removed: number } | { ok: false; reason: 'unknown-pet'; message: string }> =>\n    withMemoryLock(async () => {\n      const cfg = readAllConfig(configPaths);\n      const found = findPetInstance(cfg, petId);\n      // 与对话同一支：宠物随时可能被删，明确失败，不在文件里留没人消费的分桶\n      if (!found) return { ok: false as const, reason: 'unknown-pet' as const, message: '没有这只桌宠：' + petId };\n      // 删除代数 +1：正在生成的那一轮据此放弃写回，避免「删完又冒出来」\n      deletedEpoch.set(petId, (deletedEpoch.get(petId) ?? 0) + 1);\n      const mem = await readMemory();\n      const byPet = mem[found.entry];\n      const before = byPet?.[petId]?.messages;\n      const list = Array.isArray(before) ? before : [];\n      const kept = ts === undefined ? [] : removeRoundsByTs(list, ts).messages;\n      const removed = list.length - kept.length;\n      if (removed > 0) {\n        const leaf = byPet?.[petId];\n        if (kept.length > 0 && leaf !== undefined) {\n          leaf.messages = kept;\n        } else if (byPet !== undefined) {\n          // 清空（或本来就只剩坏数据）：摘掉宠物叶子；条目空了连条目一起摘\n          delete byPet[petId];\n          if (Object.keys(byPet).length === 0) delete mem[found.entry];\n        }\n        await writeMemory(mem);\n      }\n      // 只记数量与动作，不打正文（记忆内容是用户隐私）\n      log.info(`[dsh-pet] 删除对话记忆 pet=${petId}，removed=${removed}` + (ts === undefined ? '（清空）' : ''));\n      return { ok: true as const, removed };\n    });\n\n  /** 已删宠物残留历史的查询与清理（判定与读写细节见 ./memory-orphans）。 */\n  const { orphanHistory, deleteOrphans } = createMemoryOrphans({\n    configPaths,\n    readMemory,\n    writeMemory,\n    withLock: withMemoryLock,\n    log,\n  });\n\n  /** 当前活跃宠物 id（会话事件写入，余额与碎念读取）。 */\n  const getActivePetId = (): string => activePetId;\n\n  /** 改写当前活跃宠物 id。 */\n  const setActivePetId = (id: string): void => {\n    activePetId = id;\n  };\n  return {\n    lastWhisperAt,\n    memoryPath,\n    readMemory,\n    memoryRounds,\n    publishWhisper,\n    publishSleepTalk,\n    chatWithPet,\n    deleteHistory,\n    orphanHistory,\n    deleteOrphans,\n    getActivePetId,\n    setActivePetId,\n  };\n}\n/** 对话与记忆的产出（供下游工厂按需 Pick）。 */\nexport type ChatMemory = ReturnType<typeof createChatMemory>;\n"
    },
    {
      "path": "dsh-pet/src/host/memory/powercontext.ts",
      "content": "/**\n * 内置长期记忆实现：把本机 PowerContext 服务接到 {@link ChatMemoryProvider} 契约上。\n *\n * 召回：探到 scope → 可选地把这句话连同最近两轮改写成检索查询 → 并行检索主题记忆与原子记忆 → 分层拼成证据块前插到 userText。\n * 每步失败只放弃这一步：探测与检索失败整轮不介入，改写失败退回原句，任何情况都不阻塞对话。\n * 两层都要查：主题记忆是服务端把多轮对话沉淀成的摘要（「姐姐会缝扣子」这类关系事实只在这里），\n * 原子记忆是逐条偏好与事实（「红烧肉放两颗冰糖」这类细节只在这里），少查一层就会答不出其中一类。\n * 配置只经装配层注入的 getter 读，本模块不碰文件、不持有进程级状态（scope 缓存闭在实例里）。\n * @module dsh-pet/src/host/memory/powercontext\n */\nimport {\n  registerChatMemoryProvider,\n  resolveChatMemoryProvider,\n  type CaptureTurn,\n  type ChatMemoryProvider,\n  type ChatRequest,\n  type ChatTurn,\n  type RecallRequest,\n} from '../chat-memory-provider.ts';\nimport { defaultLog } from '../log-file.ts';\nimport { POWERCONTEXT_MEMORY_ID } from '../../shared/memory.ts';\n\n/** scope 标题：一只宠物实例一个 scope，记忆不跨宠物串。 */\nconst scopeTitleOf = (petId: string): string => 'dsh-pet:' + petId;\n/** scope 摘要：服务端建 scope 时必填（1–2000 字）。 */\nconst scopeSummaryOf = (petId: string): string => '桌面宠物 ' + petId + ' 的对话记忆，由插件自动创建。';\n/** scope 的幂等键：一只宠物一份，重复创建只会得到同一个；换掉它会多出一个删不掉的 scope。 */\nconst scopeKeyOf = (petId: string): string => 'dsh-pet:' + petId + ':v1';\n\n/** 本机 CRUD 请求的超时（ms）：探 scope、建 scope、写证据都不跑模型，慢就是服务端出问题了。 */\nconst CRUD_TIMEOUT_MS = 1_000;\n/** 检索请求的超时（ms）：hybrid 要现场调一次远程 embedding 模型，比 CRUD 慢一个量级。 */\nconst SEARCH_TIMEOUT_MS = 5_000;\n/** 改写查询的预算（ms）：超时就用原句查，宁可查得糙也不拖住对话。 */\nconst REWRITE_BUDGET_MS = 800;\n/** 召回总预算（ms）：改写预算 + 检索超时 + 余量，core 按这个值掐整轮。 */\nconst RECALL_TIMEOUT_MS = 6_000;\n/** 改写查询时带上的历史轮数（1 轮 = 1 问 1 答）：只用来还原「它」「那家」这类指代。 */\nconst REWRITE_HISTORY_ROUNDS = 2;\n/** 原子记忆检索条数：三条足够，再多只是把无关内容塞进上下文。 */\nconst RECALL_LIMIT = 3;\n/** 主题记忆检索条数：一条主题就是整段对话的摘要，比原子记忆长得多，两条已能占满半个证据块。 */\nconst TOPIC_RECALL_LIMIT = 2;\n/** 查询串的字节上限：服务端收 8192，留一半余量给中文。 */\nconst QUERY_BYTES = 4_096;\n/** 证据块的总字节上限：超了从尾部丢句子，越靠后的命中分越低。 */\nconst EVIDENCE_BYTES = 3_072;\n/** 证据块的表头：明确告诉模型这是检索到的旧信息，冲突时以用户当次输入为准。 */\nconst EVIDENCE_HEADER = '以下是从长期记忆里检索到的相关信息，供你参考；与用户这次说的话冲突时，以用户为准：';\n/** 证据块的分层标题：先给概括再给细节，模型更容易把原子条目挂到对的关系上。 */\nconst TOPIC_SECTION = '[主题记忆]';\nconst ATOM_SECTION = '[原子记忆]';\n\n/** 一次改写的输入。 */\nexport interface RewriteInput {\n  /** 用户这一句话。 */\n  readonly userText: string;\n  /** 最近 {@link REWRITE_HISTORY_ROUNDS} 轮的原文（按时间正序）；没有历史时为空。 */\n  readonly history: readonly ChatTurn[];\n}\n\n/** 装配层注入的依赖：配置读取与可选的查询改写。 */\nexport interface PowerContextDeps {\n  /** 服务根地址；空串 = 没配，整轮不介入。 */\n  readonly endpoint: () => string;\n  /** Bearer 令牌；空串 = 不带鉴权头（服务端没开认证时）。只驻内存，禁止进日志。 */\n  readonly token: () => string;\n  /** 把这句话连同最近两轮改写成检索查询；缺省或返回 undefined 时用原句。 */\n  readonly rewrite?: (input: RewriteInput) => Promise<string | undefined>;\n}\n\n/** 检索命中里本模块真正用到的两个字段。 */\ninterface MemoryHit {\n  readonly kind: string;\n  readonly text: string;\n}\n\n/** 主题记忆命中：服务端只给标题与摘要，本模块用这两段拼一行证据。 */\ninterface TopicHit {\n  readonly title: string;\n  readonly summary: string;\n}\n\n/** 一次召回的两层结果；`undefined` 表示该层失败，空数组表示查到了但没有命中。 */\ninterface RecallLayers {\n  readonly topics: readonly TopicHit[] | undefined;\n  readonly atoms: readonly MemoryHit[] | undefined;\n}\n\n/**\n * 造 PowerContext 记忆实现。\n *\n * @param deps - 地址与令牌的读取口，外加可选的查询改写。\n * @returns 注册表认得的内置实现。\n */\nexport function createPowerContextMemory(deps: PowerContextDeps): ChatMemoryProvider {\n  /** 已探测到的 scope：一只宠物一份，键里带上地址——换了服务器不能继续往旧 scope 写。 */\n  const scopes = new Map<string, string>();\n\n  /**\n   * 取某只宠物的 scope id：先按标题查，没有才创建。\n   *\n   * 不用「幂等 POST 兜底创建」：那条路对已存在的 scope 会返回 409，语义不明确；\n   * 查询 + 创建虽然多一次往返，但「检测」与「创建」各自的结果都确定。\n   */\n  const ensureScope = async (petId: string): Promise<string | undefined> => {\n    const endpoint = deps.endpoint().trim();\n    if (endpoint === '') return undefined;\n    const cacheKey = endpoint + '\\u0000' + petId;\n    const cached = scopes.get(cacheKey);\n    if (cached !== undefined) return cached;\n    const title = scopeTitleOf(petId);\n    const page = await callApi(deps, {\n      method: 'GET',\n      path: '/v1/scopes?query=' + encodeURIComponent(title) + '&query_field=title&limit=50',\n      timeoutMs: CRUD_TIMEOUT_MS,\n    });\n    const items = (page as { items?: unknown } | undefined)?.items;\n    if (!Array.isArray(items)) return undefined;\n    // 服务端的 query 是模糊匹配，可能连 \"dsh-pet:pet-20\" 一起返回，所以按标题精确比对\n    const found = items.find((item) => (item as { title?: unknown }).title === title);\n    const known = (found as { scope_id?: unknown } | undefined)?.scope_id;\n    if (typeof known === 'string' && known !== '') {\n      scopes.set(cacheKey, known);\n      return known;\n    }\n    const created = await callApi(deps, {\n      method: 'POST',\n      path: '/v1/scopes',\n      body: {\n        title,\n        summary: scopeSummaryOf(petId),\n        idempotency_key: scopeKeyOf(petId),\n      },\n      timeoutMs: CRUD_TIMEOUT_MS,\n    });\n    const id = (created as { scope_id?: unknown } | undefined)?.scope_id;\n    if (typeof id !== 'string' || id === '') return undefined;\n    scopes.set(cacheKey, id);\n    return id;\n  };\n\n  /** 查询串：改写优先（带最近两轮还原指代），没有就用原话；按字节截断，服务端限 8192。 */\n  const buildQuery = async (req: RecallRequest): Promise<string> => {\n    const rewritten = await rewriteWithin(deps.rewrite, {\n      userText: req.userText,\n      history: req.prepared.history.slice(-REWRITE_HISTORY_ROUNDS * 2),\n    });\n    return truncateBytes(rewritten ?? req.userText, QUERY_BYTES);\n  };\n\n  const recall = async (req: RecallRequest): Promise<ChatRequest | undefined> => {\n    const scopeId = await ensureScope(req.petId);\n    if (scopeId === undefined) return undefined;\n    const query = await buildQuery(req);\n    if (query === '') return undefined;\n    // 两层并行：总耗时取较慢的那一路，不让一层慢拖成两层的和。\n    const [topics, atoms] = await Promise.all([searchTopics(deps, scopeId, query), search(deps, scopeId, query)]);\n    const evidence = formatEvidence({ topics, atoms });\n    if (evidence === '') {\n      logEmptyRecall(req.petId, topics, atoms);\n      return undefined;\n    }\n    return { ...req.prepared, userText: evidence + '\\n\\n' + req.prepared.userText };\n  };\n\n  const capture = async (turn: CaptureTurn): Promise<void> => {\n    const scopeId = await ensureScope(turn.petId);\n    if (scopeId === undefined) return;\n    // 写的是 CaptureContentSourceRequest（202 受理，抽取在服务端后台跑）。\n    // source_id 只带轮次时间戳：唯一性按 (scope, source_id) 算，而 scope 已是「一只宠物一个」，重试仍得同一个 id。\n    // 注意不能走 /v1/scopes/{id}/sources——那条路收的是 CreateSourceRequest，不认 scope_id 与 source_id。\n    await callApi(deps, {\n      method: 'POST',\n      path: '/v1/sources/content',\n      body: {\n        scope_id: scopeId,\n        source_id: 'dsh-pet:' + turn.ts,\n        content: '用户：' + turn.userText + '\\n宠物：' + turn.replyText,\n      },\n      timeoutMs: CRUD_TIMEOUT_MS,\n    });\n  };\n\n  return {\n    id: POWERCONTEXT_MEMORY_ID,\n    name: 'PowerContext',\n    timeoutMs: RECALL_TIMEOUT_MS,\n    recall,\n    capture,\n  };\n}\n\n/**\n * 确保内置 PowerContext 实现在注册表里；重复调用无副作用（多次装配、热重载都会经过这里）。\n *\n * 已经注册过时直接返回，不去覆盖同 id 的另一份。\n *\n * @param deps - 地址与令牌的读取口，外加可选的查询改写。\n */\nexport function ensurePowerContextMemory(deps: PowerContextDeps): void {\n  if (resolveChatMemoryProvider(POWERCONTEXT_MEMORY_ID).id === POWERCONTEXT_MEMORY_ID) return;\n  registerChatMemoryProvider(createPowerContextMemory(deps));\n}\n\n/** 一次出站请求。 */\ninterface ApiCall {\n  readonly method: 'GET' | 'POST';\n  /** 以 `/` 开头的服务端路径（含查询串）。 */\n  readonly path: string;\n  /** 请求体；缺省表示不带体。 */\n  readonly body?: unknown;\n  /** 单次超时（ms）：检索要跑向量化，跟 CRUD 不是一个量级，由调用方各自给。 */\n  readonly timeoutMs: number;\n}\n\n/**\n * 发一次 JSON 请求。\n *\n * 超时、断网、非 2xx、响应不是 JSON 一律回 `undefined`——调用方只按「这步没成」处理。\n * 错误只记端点与状态码：地址里可能带内网主机名，令牌更是不该出现在日志里。\n *\n * @param deps - 取地址与令牌。\n * @param call - 方法、路径、请求体与本次超时。\n * @returns 解析后的 JSON 值，未校验形状（调用方逐字段判）。\n */\nasync function callApi(deps: PowerContextDeps, call: ApiCall): Promise<unknown> {\n  const base = deps.endpoint().trim().replace(/\\/+$/, '');\n  if (base === '') return undefined;\n  const token = deps.token().trim();\n  try {\n    const response = await fetch(base + call.path, {\n      method: call.method,\n      headers: {\n        'content-type': 'application/json',\n        ...(token === '' ? {} : { authorization: 'Bearer ' + token }),\n      },\n      ...(call.body === undefined ? {} : { body: JSON.stringify(call.body) }),\n      signal: AbortSignal.timeout(call.timeoutMs),\n    });\n    if (!response.ok) {\n      defaultLog(\n        'warn',\n        'dsh-pet: PowerContext ' + call.method + ' ' + call.path.split('?')[0] + ' 返回 HTTP ' + response.status,\n      );\n      return undefined;\n    }\n    return await response.json();\n  } catch {\n    return undefined;\n  }\n}\n\n/** 检索原子记忆（逐条偏好与事实）；响应形状不对按失败处理。 */\nasync function search(deps: PowerContextDeps, scopeId: string, query: string): Promise<MemoryHit[] | undefined> {\n  const result = await callApi(deps, {\n    method: 'POST',\n    path: '/v1/atomic-memory/search',\n    body: {\n      scope_id: scopeId,\n      query,\n      mode: 'hybrid',\n      limit: RECALL_LIMIT,\n    },\n    timeoutMs: SEARCH_TIMEOUT_MS,\n  });\n  const hits = (result as { hits?: unknown } | undefined)?.hits;\n  if (!Array.isArray(hits)) return undefined;\n  return hits.map(toHit).filter((hit): hit is MemoryHit => hit !== undefined);\n}\n\n/** 检索主题记忆（多轮对话沉淀成的摘要）；响应形状不对同样按失败处理。 */\nasync function searchTopics(deps: PowerContextDeps, scopeId: string, query: string): Promise<TopicHit[] | undefined> {\n  const result = await callApi(deps, {\n    method: 'POST',\n    path: '/v1/topic-memory/search',\n    body: {\n      scope_id: scopeId,\n      query,\n      limit: TOPIC_RECALL_LIMIT,\n    },\n    timeoutMs: SEARCH_TIMEOUT_MS,\n  });\n  const hits = (result as { hits?: unknown } | undefined)?.hits;\n  if (!Array.isArray(hits)) return undefined;\n  return hits.map(toTopicHit).filter((hit): hit is TopicHit => hit !== undefined);\n}\n\n/** 一条命中 → `{ kind, text }`；缺字段或空文本当没有这一条。 */\nfunction toHit(value: unknown): MemoryHit | undefined {\n  const memory = (value as { memory?: unknown } | undefined)?.memory;\n  if (!memory || typeof memory !== 'object') return undefined;\n  const record = memory as { kind?: unknown; text?: unknown };\n  if (typeof record.text !== 'string' || record.text === '') return undefined;\n  return { kind: typeof record.kind === 'string' ? record.kind : '', text: record.text };\n}\n\n/** 一条主题命中 → `{ title, summary }`；只有标题没有正文的条目对模型没有信息量，丢弃。 */\nfunction toTopicHit(value: unknown): TopicHit | undefined {\n  const hit = value as { title?: unknown; summary?: unknown; snippet?: unknown } | undefined;\n  const summary = textField(hit?.summary) || textField(hit?.snippet);\n  if (summary === '') return undefined;\n  return { title: textField(hit?.title), summary };\n}\n\n/** 取一个字符串字段并去首尾空白；非字符串按空串处理。 */\nfunction textField(value: unknown): string {\n  return typeof value === 'string' ? value.trim() : '';\n}\n\n/** 一条主题命中的展示行：`- 标题：摘要`；标题为空时只给摘要。 */\nfunction topicLine(hit: TopicHit): string {\n  return '- ' + (hit.title === '' ? '' : hit.title + '：') + hit.summary;\n}\n\n/** 证据块的一段：段标题与已按分数降序排好的行。 */\ntype EvidenceSection = readonly [title: string, lines: readonly string[]];\n\n/**\n * 把两层命中分层拼成证据块。\n *\n * 主题段在原子段之前：主题概括的是一整段关系，原子条目是细节，先给概括模型才挂得对地方。\n *\n * @param layers - 两层的命中；某一层为 `undefined` 时按空处理，只剩一层也照常输出。\n * @returns 以表头开头的证据块；空串表示没有任何可用命中。\n */\nfunction formatEvidence(layers: RecallLayers): string {\n  const lines = fitSections([\n    [TOPIC_SECTION, (layers.topics ?? []).map(topicLine)],\n    [ATOM_SECTION, (layers.atoms ?? []).map((hit) => evidenceLine(hit.kind, hit.text))],\n  ]);\n  return lines.length === 0 ? '' : EVIDENCE_HEADER + '\\n' + lines.join('\\n');\n}\n\n/**\n * 在字节预算内摆放各段，段标题与每一行都计入。\n *\n * 超长从尾部丢整条：越靠后的命中分越低，先丢它们的损失最小。\n * 首条就放不下时截断塞进去——单条啰嗦记忆不该让整轮召回作废。\n *\n * @param sections - 按展示顺序排列的段。\n * @returns 放得下的行；空数组表示连第一个段标题都放不下。\n */\nfunction fitSections(sections: readonly EvidenceSection[]): string[] {\n  const out: string[] = [];\n  let used = Buffer.byteLength(EVIDENCE_HEADER, 'utf8');\n  let hasContent = false;\n  for (const [title, lines] of sections) {\n    if (lines.length === 0) continue;\n    const titleCost = Buffer.byteLength('\\n' + title, 'utf8');\n    if (used + titleCost > EVIDENCE_BYTES) break;\n    out.push(title);\n    used += titleCost;\n    for (const line of lines) {\n      const size = Buffer.byteLength('\\n' + line, 'utf8');\n      if (used + size <= EVIDENCE_BYTES) {\n        out.push(line);\n        used += size;\n        hasContent = true;\n        continue;\n      }\n      if (hasContent) return out;\n      const room = EVIDENCE_BYTES - used - 1;\n      const truncated = room > 0 ? truncateBytes(line, room) : '';\n      if (truncated === '') return out;\n      out.push(truncated);\n      return out;\n    }\n  }\n  return out;\n}\n\n/** 一条原子记忆命中的展示行：`- [kind] 正文`。 */\nfunction evidenceLine(kind: string, text: string): string {\n  return '- ' + (kind === '' ? '' : '[' + kind + '] ') + text;\n}\n\n/**\n * 记一行「这轮召回是空的」。\n *\n * 召回为空有三条路：scope 探不到、检索失败、命中 0 条。过去三条都是静默返回，\n * 出问题时只能手工去问服务端；分层的状态写进同一行，看日志就能分清是哪条路。\n *\n * @param petId - 目标宠物；日志按它定位。\n * @param topics - 主题记忆那一路的结果。\n * @param atoms - 原子记忆那一路的结果。\n */\nfunction logEmptyRecall(\n  petId: string,\n  topics: readonly TopicHit[] | undefined,\n  atoms: readonly MemoryHit[] | undefined,\n): void {\n  const describe = (list: readonly unknown[] | undefined): string =>\n    list === undefined ? '失败' : list.length + ' 条';\n  const line =\n    'dsh-pet: PowerContext 记忆召回无命中 pet=' +\n    petId +\n    '（主题 ' +\n    describe(topics) +\n    '，原子 ' +\n    describe(atoms) +\n    '）';\n  // 两层都失败多半是服务没起、地址或令牌不对，与「查到了但没命中」不是一类问题\n  if (topics === undefined && atoms === undefined) defaultLog('warn', line);\n  else defaultLog('info', line);\n}\n\n/** 在预算内改写查询；超时、抛错、返回空串都当没改写。 */\nasync function rewriteWithin(rewrite: PowerContextDeps['rewrite'], input: RewriteInput): Promise<string | undefined> {\n  if (rewrite === undefined) return undefined;\n  const budget = AbortSignal.timeout(REWRITE_BUDGET_MS);\n  const deadline = new Promise<undefined>((resolve) => {\n    budget.addEventListener('abort', () => resolve(undefined), { once: true });\n  });\n  const attempt = Promise.resolve()\n    .then(() => rewrite(input))\n    .catch(() => undefined);\n  const text = await Promise.race([attempt, deadline]);\n  if (typeof text !== 'string') return undefined;\n  const normalized = text.replace(/\\s+/g, ' ').trim();\n  return normalized === '' ? undefined : normalized;\n}\n\n/** 按 UTF-8 字节截断；不会把多字节字符切半个。 */\nfunction truncateBytes(text: string, limit: number): string {\n  if (Buffer.byteLength(text, 'utf8') <= limit) return text;\n  let out = '';\n  let used = 0;\n  for (const char of text) {\n    const size = Buffer.byteLength(char, 'utf8');\n    if (used + size > limit) break;\n    out += char;\n    used += size;\n  }\n  return out;\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/todo-reminders.ts",
      "content": "/**\n * 待办提醒循环：定时挑一条到点的待办，让当前可见的桌宠说一句。\n *\n * 不决定节奏与文案（归 ../todo/policy），也不读写文件（归 ../todo/store）。\n * 每拍最多说一条，避免多条同时到期时刷屏；写进 S 之后才记 lastRemindedAt，重启不会重复。\n * 没有可见宠物或被第三方占用时跳过且不推进——条件满足后的下一拍立刻补上，这次提醒不会丢。\n * @module dsh-pet/src/host/plugin/todo-reminders\n */\nimport { pickVoiceSurface } from '../surface.ts';\nimport { pickReminder, reminderText } from '../todo/policy.ts';\nimport type { TodoStore } from '../todo/store.ts';\nimport type { LockStore } from '../lock.ts';\nimport type { PollStateStore } from '../state.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { PetLookup } from './pet-lookup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 巡检查找间隔（ms）：比最短提醒间隔（5 分钟）小一档即可，不必更密。 */\nconst TICK_MS = 60 * 1000;\n\n/** 提醒气泡停留时长（ms）：比默认 10 秒久一点，欠着的事值得多看两眼。 */\nconst BUBBLE_DURATION_MS = 15 * 1000;\n\n/** 一拍所需的最小能力（与完整输入同形，便于测试替身）。 */\nexport interface TodoReminderTickDeps {\n  /** 待办存储：读清单、记提醒时刻。 */\n  todos: Pick<TodoStore, 'list' | 'markReminded'>;\n  /** 当前生效的宠物列表（成品配置拍平）。 */\n  effectivePetList: () => Record<string, unknown>[];\n  /** 占用锁：被第三方占用的宠物这一拍不打扰。 */\n  lock: Pick<LockStore, 'locked'>;\n  /** 睡着的宠物不打扰：提醒是「跟它说话」，睡着时说了它也听不见，换一只醒着的。\n   *  缺省视为都不睡（老调用方与测试替身不必改）。 */\n  isSleeping?: (petId: string) => boolean;\n  /** 轮询状态：提醒写进 `pets.<id>.say`。 */\n  state: Pick<PollStateStore, 'writePet'>;\n  /** 日志出口。 */\n  log: Pick<HostSetup['log'], 'info' | 'warn'>;\n  /** 时间源；测试注入固定时钟。 */\n  now?: () => number;\n  /** 是否有端在线（长轮询在挂）。没有就不提醒：写进 S 也没人看见，还白白推进了排期。 */\n  hasListener?: () => boolean;\n  /** 待办播报开关（成品配置的 `main.voiceTodoEnabled`）：关着就不写 `voiceTo`，只弹气泡。 */\n  isVoiceTodoEnabled: () => boolean;\n}\n\n/** 提醒循环的输入。 */\nexport type TodoReminderInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n  /** 当前挂着长轮询的端数量：>0 表示有人能看到这次提醒。 */\n  waiterCount: () => number;\n} & Pick<PetLookup, 'lock'> &\n  Pick<PetLookup, 'sleep'> &\n  Pick<TodoReminderTickDeps, 'todos' | 'effectivePetList' | 'state' | 'log' | 'isVoiceTodoEnabled'>;\n/**\n * 挑一个承担这次提醒的宠物：优先网页端可见的，其次桌面端；被第三方占用的跳过。\n *\n * @param pets - 成品配置拍平后的宠物列表。\n * @param isLocked - 该宠物是否正被占用。\n * @returns 宠物 id；没有可用的返回 null。\n * @internal\n */\nexport function pickReminderSpeaker(\n  pets: readonly Record<string, unknown>[],\n  isLocked: (petId: string) => boolean,\n  isSleeping: (petId: string) => boolean = () => false,\n): string | null {\n  let desktopOnly: string | null = null;\n  for (const pet of pets) {\n    const petId = String(pet.id ?? '');\n    if (petId === '') continue;\n    if (pet.display === 'none') continue;\n    if (isLocked(petId)) continue;\n    if (isSleeping(petId)) continue;\n    if (pet.display === 'web' || pet.display === 'both') return petId;\n    desktopOnly ??= petId;\n  }\n  return desktopOnly;\n}\n\n/**\n * 跑一拍：最多提醒一条，成功后记下提醒时刻。\n *\n * @param deps - 存储、宠物列表、锁与状态写入。\n * @returns 无返回值；没有到点或没有可开口的宠物时静默返回。\n */\nexport async function tickTodoReminders(deps: TodoReminderTickDeps): Promise<void> {\n  // 没有端在线时整拍跳过、不推进 lastRemindedAt：下一次有人连上时还是「到点」状态。\n  if (deps.hasListener !== undefined && !deps.hasListener()) return;\n  const now = deps.now?.() ?? Date.now();\n  const due = pickReminder(await deps.todos.list(), now);\n  if (due === null) return;\n  const pets = deps.effectivePetList();\n  const speaker = pickReminderSpeaker(\n    pets,\n    (petId) => deps.lock.locked(petId),\n    (petId) => deps.isSleeping?.(petId) ?? false,\n  );\n  if (speaker === null) return;\n  // 该由哪一端念：pickReminderSpeaker 已排除 display=none，所以这里不会是 null（防御性保留可选）；\n  // 播报开关关掉时干脆不写这个键（叶子不带 = 谁都不念），气泡照旧弹。\n  const display = String(pets.find((pet) => String(pet.id ?? '') === speaker)?.display ?? '');\n  const voiceTo = deps.isVoiceTodoEnabled() ? pickVoiceSurface(display) : null;\n  deps.state.writePet(speaker, 'say', {\n    text: reminderText(due.todo, now),\n    duration: BUBBLE_DURATION_MS,\n    ...(voiceTo ? { voiceTo } : {}),\n  });\n  await deps.todos.markReminded(due.todo.id, now);\n  // 只记 id 与剩余时长：待办正文是用户内容，不进日志。\n  const remainingSec = due.todo.dueAt === null ? 0 : Math.round((due.todo.dueAt - now) / 1000);\n  deps.log.info(`[dsh-pet] 待办提醒 todo=${due.todo.id} pet=${speaker} 剩余=${remainingSec}s`);\n}\n\n/**\n * 注册提醒循环；返回的清理函数由 ctx.effect 收集。\n *\n * @param deps - 宿主上下文与一拍所需的能力。\n */\nexport function registerTodoReminders(deps: TodoReminderInput): void {\n  const { ctx, effectivePetList, isVoiceTodoEnabled, lock, log, sleep, state, todos, waiterCount } = deps;\n\n  /** 一拍：失败只打日志，不让循环停摆。 */\n  const tick = async (): Promise<void> => {\n    try {\n      await tickTodoReminders({\n        effectivePetList,\n        hasListener: () => waiterCount() > 0,\n        isSleeping: (petId) => sleep.sleeping(petId),\n        isVoiceTodoEnabled,\n        lock,\n        log,\n        state,\n        todos,\n      });\n    } catch (error) {\n      log.warn('[dsh-pet] 待办提醒失败：' + (error instanceof Error ? error.message : String(error)));\n    }\n  };\n\n  ctx.effect(() => {\n    let disposed = false;\n    let timer: ReturnType<typeof setTimeout> | null = null;\n\n    /** 排下一拍；已卸载就不再排。 */\n    function arm(): void {\n      if (disposed) return;\n      timer = setTimeout(() => void run(), TICK_MS);\n    }\n\n    /** 跑一拍再排下一拍：启动即检查一次，不等第一个周期。 */\n    async function run(): Promise<void> {\n      timer = null;\n      await tick();\n      arm();\n    }\n\n    void run();\n    return () => {\n      disposed = true;\n      if (timer !== null) clearTimeout(timer);\n    };\n  }, 'dsh-pet: todo reminders');\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/loops.ts",
      "content": "/**\n * 轮询循环：余额定时刷新与碎碎念定时触发，随插件卸载一并停止。\n *\n * 不实现取数与文案（归 balance-poll / chat-memory），只负责节奏与生命周期。\n * @module dsh-pet/src/host/plugin/loops\n */\nimport { findPetInstance, flattenPetList, readAllConfig } from '../config.ts';\nimport { isDisplayed } from '../surface.ts';\nimport { automaticWhisperSchedule } from '../whisper-policy.ts';\nimport { clampPeriodSec } from './period.ts';\nimport type { BalancePoll } from './balance-poll.ts';\nimport type { ChatMemory } from './chat-memory.ts';\nimport type { PetLookup } from './pet-lookup.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 梦话周期的兜底值（秒）：配置里 eventsRefreshSec.sleepTalk 缺失/非法时用它。 */\nconst SLEEP_TALK_DEFAULT_SEC = 60;\n\n/** 错峰队列里相邻两只之间的间隔（ms）：同拍到点的宠物依次开口，才会错开冒泡与语音。 */\nconst WHISPER_STAGGER_MS = 10_000;\n\n/** 错峰队列上限：6 只 × 10s = 60s，正好覆盖最短周期，队列不会追着拍跑。 */\nconst WHISPER_QUEUE_MAX = 6;\n\n/** 轮询循环的输入。 */\nexport type LoopsInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<BalancePoll, 'balancePeriodSec'> &\n  Pick<HostSetup, 'configPaths'> &\n  Pick<ChatMemory, 'lastWhisperAt'> &\n  Pick<PetLookup, 'lock'> &\n  Pick<PetLookup, 'sleep'> &\n  Pick<HostSetup, 'log'> &\n  Pick<ChatMemory, 'publishWhisper'> &\n  Pick<ChatMemory, 'publishSleepTalk'> &\n  Pick<BalancePoll, 'refreshBalance'> &\n  Pick<HostSetup, 'standaloneAiPolicy'> &\n  Pick<BalancePoll, 'whisperPeriodSec'>;\n\n/** 注册轮询循环；返回的清理函数由 ctx.effect 收集。 */\nexport function registerLoops(deps: LoopsInput): void {\n  const {\n    ctx,\n    balancePeriodSec,\n    configPaths,\n    lastWhisperAt,\n    lock,\n    log,\n    publishWhisper,\n    publishSleepTalk,\n    refreshBalance,\n    sleep,\n    standaloneAiPolicy,\n    whisperPeriodSec,\n  } = deps;\n  // 余额周期刷新：host 侧唯一定时器。周期每次重新读配置 eventsRefreshSec.balance，改了下一拍跟上。\n  // 没有任何启用余额的宠物时跳过查询：尊重配置，不白花外部 API 调用。\n  ctx.effect(() => {\n    let disposed = false;\n    let timer: ReturnType<typeof setTimeout> | null = null;\n    function arm(sec: number): void {\n      if (disposed) return;\n      timer = setTimeout(() => void tick(), Math.max(1000, sec * 1000));\n    }\n    async function tick(): Promise<void> {\n      let sec: number;\n      try {\n        const cfg = readAllConfig(configPaths);\n        sec = balancePeriodSec(cfg);\n        // 没有任何「醒着且启用余额」的宠物 → 不查（省外部调用）：睡着的宠物不看不听，\n        // 拉了也只会白花一次外部 API；配置改了或醒了，下一拍自然跟上。\n        const pets = flattenPetList(cfg);\n        if (pets.some((p) => p.balanceEnabled === true && !sleep.sleeping(String(p.id ?? '')))) {\n          await refreshBalance();\n        } else {\n          log.info('[dsh-pet] 余额周期跳过：没有醒着且启用余额的宠物');\n        }\n      } catch (e) {\n        // 读配置抛错 = 安装损坏（readAllConfig 只在内置默认缺失/损坏时抛，用户层写坏只会告警回退）：\n        // 不再重排——每 30 分钟重试一次没有意义，而且会白占一个常驻定时器。留一行 warn：这条路径\n        // 会让余额周期永久停摆，不打日志就与「查了但没变化」无法区分。\n        log.warn(\n          '[dsh-pet] 余额周期读配置失败，周期刷新已停止（重启 DSH 后恢复）：' +\n            (e instanceof Error ? e.message : String(e)),\n        );\n        return;\n      }\n      arm(sec);\n    }\n    void tick(); // 启动即拉一次，不等第一个周期\n    return () => {\n      disposed = true;\n      if (timer !== null) clearTimeout(timer);\n    };\n  }, 'dsh-pet: balance poll');\n\n  // 碎碎念周期：host 侧调度。一拍 = 读一次配置 + 把「到点」的宠物排进错峰队列；下一拍按最短周期排。\n  // 用固定拍 + 逐宠物比对 lastWhisperAt，而不是每宠一个定时器：宠物随配置增删、周期随条目改，\n  // 固定拍天然跟上，不用维护一堆定时器的生命周期。\n  ctx.effect(() => {\n    let disposed = false;\n    let timer: ReturnType<typeof setTimeout> | null = null;\n    /** 待发布的宠物（FIFO）；一次只发一只，两只之间隔 {@link WHISPER_STAGGER_MS}。 */\n    const pending: string[] = [];\n    /** 队列内相邻两只之间的等待句柄；与拍定时器分开计，两者都要在卸载时清掉。 */\n    let drainTimer: ReturnType<typeof setTimeout> | null = null;\n\n    /** 是否已经有一只正在生成；同一时刻只允许一只，否则两只仍会同时写出气泡。 */\n    let pumping = false;\n\n    /**\n     * 从队列取下一只发布，等它写完再隔一个间隔发下一只。\n     *\n     * 间隔从「文字真的写进状态」算起，而不是从发起点算：单次生成耗时在 3–15 秒之间波动，\n     * 从发起点算的固定间隔会被慢的那只吃掉，两只又撞到一起。\n     */\n    async function pump(): Promise<void> {\n      if (disposed || pumping || drainTimer !== null) return;\n      const petId = pending.shift();\n      if (petId === undefined) return;\n      pumping = true;\n      try {\n        // kind=whisper 让生成侧按 voiceWhisperEnabled 决定要不要带 voiceTo。\n        await publishWhisper(petId, undefined, undefined, 'whisper');\n      } catch {\n        // 单只失败不挡住后面的宠物：原因已经由 publishWhisper 记过日志。\n      } finally {\n        pumping = false;\n      }\n      if (disposed || pending.length === 0) return;\n      drainTimer = setTimeout(() => {\n        drainTimer = null;\n        void pump();\n      }, WHISPER_STAGGER_MS);\n    }\n\n    function arm(sec: number): void {\n      if (disposed) return;\n      timer = setTimeout(() => void tick(), Math.max(1000, sec * 1000));\n    }\n    function tick(): void {\n      let next = 300;\n      try {\n        const cfg = readAllConfig(configPaths);\n        const now = Date.now();\n        let min = Infinity;\n        // 每一拍的账：检查几只、到点几只、没到点几只、跳过几只（带原因）。只用于日志，调度行为不变。\n        let checked = 0;\n        let due = 0;\n        let notDue = 0;\n        const skipped: string[] = [];\n        for (const pet of flattenPetList(cfg)) {\n          const petId = String(pet.id ?? '');\n          if (!petId) continue;\n          // petId 就是从同一份 cfg 拍平出来的，所以必然命中（findPetInstance 与 flattenPetList\n          // 搜索同一集合）；查不到只可能是两者口径漂移——跳过这一拍，不猜也不兜底 main。\n          const found = findPetInstance(cfg, petId);\n          if (!found) continue;\n          checked += 1;\n          const schedule = automaticWhisperSchedule(\n            standaloneAiPolicy(),\n            pet.whisperEnabled === true,\n            whisperPeriodSec(found.conf),\n          );\n          if (!schedule.enabled) {\n            // 两种「没启用」分开记：宠物自己关掉，与独立模式 AI 未就绪，处理方式完全不同\n            skipped.push(petId + ': ' + (pet.whisperEnabled === true ? '独立模式 AI 未就绪' : 'whisperEnabled=false'));\n            continue;\n          }\n          // 配置上不显示的宠物不生成：用户选「都不显示」就是不用了，后台继续调模型纯属白烧额度（#237）。\n          // 放在 min 之前：不可见的宠物也不该把整拍的周期拖住。不推进 lastWhisperAt——\n          // 与占用锁同一口径，重新可见后下一拍立刻补一句。\n          const display = String(pet.display ?? '');\n          if (!isDisplayed(display)) {\n            skipped.push(petId + ': display=none');\n            continue;\n          }\n          const sec = schedule.periodSec;\n          min = Math.min(min, sec);\n          if (now - (lastWhisperAt.get(petId) ?? 0) < sec * 1000) {\n            notDue += 1;\n            continue;\n          }\n          // 占用锁：这只宠物被占用时跳过这一拍——不生成也不补（碎碎念是瞬时事件，过期即弃），\n          // 且不推进 lastWhisperAt：锁一放开，下一拍就该照常说。\n          // 只挡这一处 per-pet 来源；全局段（balance / workStatus）由渲染端按宠物忽略——\n          // 宿主跳过写入会连带静音别的宠物。\n          if (lock.locked(petId)) {\n            skipped.push(petId + ': 占用锁跳过');\n            continue;\n          }\n          // 睡觉：不生成、也不推进 lastWhisperAt——醒来的下一拍立刻补一句，与占用锁同一口径。\n          if (sleep.sleeping(petId)) {\n            skipped.push(petId + ': 睡觉中');\n            continue;\n          }\n          // 队列有上限：宠物多、周期短时宁可这一拍少说几句，也不让错峰追着下一拍跑。\n          if (pending.length >= WHISPER_QUEUE_MAX) {\n            skipped.push(petId + ': 错峰队列已满');\n            continue;\n          }\n          due += 1;\n          // 在调度时记：排队不改变周期语义，单只仍然每 sec 秒一句。\n          lastWhisperAt.set(petId, now);\n          log.info(`[dsh-pet] 碎碎念到点 pet=${petId}（周期 ${sec}s），入队待发`);\n          pending.push(petId);\n        }\n        void pump(); // 本拍到点的宠物开始逐只发布\n        if (Number.isFinite(min)) next = min;\n        // 每拍一行汇总：调度是否还在跑、下一拍多久、为什么跳过，全在这一行里（300s 一条，量可忽略）\n        log.info(\n          `[dsh-pet] 碎碎念调度：检查 ${checked} 只 → 到点 ${due}、未到点 ${notDue}、跳过 ${skipped.length}` +\n            (due > 1 ? `；${due} 只按 ${WHISPER_STAGGER_MS / 1000}s 间隔依次说` : '') +\n            (skipped.length > 0 ? `（${skipped.join('；')}）` : '') +\n            `；下一拍 ${next}s`,\n        );\n      } catch (e) {\n        // 读配置抛错 = 安装损坏（同余额定时器）：不再重排，别白占常驻句柄。\n        // 但必须留一行 warn：这条路径会让自动碎碎念永久停摆。\n        log.warn(\n          '[dsh-pet] 碎碎念调度读配置失败，自动碎碎念已停止（重启 DSH 后恢复）：' +\n            (e instanceof Error ? e.message : String(e)),\n        );\n        return;\n      }\n      arm(next);\n    }\n    void tick(); // 启动即生成一次，不等第一个周期\n    return () => {\n      disposed = true;\n      if (timer !== null) clearTimeout(timer);\n      if (drainTimer !== null) clearTimeout(drainTimer);\n    };\n  }, 'dsh-pet: whisper poll');\n\n  // 梦话周期：只对正在睡的宠物，按各自条目的 eventsRefreshSec.sleepTalk 排。\n  // 与碎碎念同一个形态（固定拍 + 逐宠物比对 lastAt），宠物增删与周期改动天然跟上。\n  ctx.effect(() => {\n    let disposed = false;\n    let timer: ReturnType<typeof setTimeout> | null = null;\n    /** petId → 上一次说梦话的时刻；醒来不清，下次睡着时按周期自然接着算。 */\n    const lastTalkAt = new Map<string, number>();\n    function arm(sec: number): void {\n      if (disposed) return;\n      timer = setTimeout(() => void tick(), Math.max(1000, sec * 1000));\n    }\n    function tick(): void {\n      let next = SLEEP_TALK_DEFAULT_SEC;\n      try {\n        const cfg = readAllConfig(configPaths);\n        const now = Date.now();\n        let min = Infinity;\n        for (const petId of sleep.ids()) {\n          const found = findPetInstance(cfg, petId);\n          if (!found) continue;\n          // 与碎碎念同口径：关掉碎碎念的宠物不再有任何后台生成，配置上不显示的也不生成（#237）。\n          // 放在 min 之前：被跳过的宠物不该把整拍的周期拖住。不推进 lastTalkAt——重新可见后下一拍立刻补一句。\n          if (!shouldSleepTalk(found.pet)) continue;\n          const sec = sleepTalkPeriodSec(found.conf);\n          min = Math.min(min, sec);\n          if (now - (lastTalkAt.get(petId) ?? 0) < sec * 1000) continue;\n          lastTalkAt.set(petId, now);\n          // 不 await：生成要几秒，别把调度拍拖住\n          void publishSleepTalk(petId).catch(() => {});\n        }\n        if (Number.isFinite(min)) next = min;\n      } catch (e) {\n        // 读配置抛错 = 安装损坏：停止本循环并留一行日志（与另外两个循环同一口径）\n        log.warn(\n          '[dsh-pet] 梦话调度读配置失败，说梦话已停止（重启 DSH 后恢复）：' +\n            (e instanceof Error ? e.message : String(e)),\n        );\n        return;\n      }\n      arm(next);\n    }\n    void tick();\n    return () => {\n      disposed = true;\n      if (timer !== null) clearTimeout(timer);\n    };\n  }, 'dsh-pet: sleep talk poll');\n}\n\n/**\n * 这只宠物这一刻该不该说梦话。\n *\n * 两道判定与碎碎念同口径：宠物自己关掉碎碎念就不再有任何后台生成；配置上不显示的\n * 宠物也不生成——用户选「都不显示」就是不用了，后台继续调模型纯属白烧额度（#237）。\n *\n * @param pet - 成品配置拍平后的宠物条目。\n * @returns 两道判定都通过时为 true。\n * @internal\n */\nexport function shouldSleepTalk(pet: Record<string, unknown>): boolean {\n  if (pet.whisperEnabled !== true) return false;\n  return isDisplayed(String(pet.display ?? ''));\n}\n\n/** 梦话周期（秒）：条目级 eventsRefreshSec.sleepTalk，读不到按 60 兜底（与配置注释同一口径）。 */\nfunction sleepTalkPeriodSec(conf: Record<string, unknown>): number {\n  const table = conf.eventsRefreshSec as Record<string, unknown> | undefined;\n  return clampPeriodSec(table?.sleepTalk, SLEEP_TALK_DEFAULT_SEC);\n}\n"
    },
